/** The whole stylesheet: tokens, base and prose. */
export const css: string = "/*\n * Tempra design tokens: the one place values live (TEMPRA-8). Take 2 of the design (TEMPRA-53,\n * design/handoff/layout-take-2) set structure and type: neutral greys, a serif for concept bodies,\n * a type scale, radii and one soft shadow. Take 3 (TEMPRA-106, design/handoff/layout-take-3) set\n * the frame's sizes, squarer corners and the one colour allowed before the palette: a small warm\n * dot for an agent's recent change. Take 4 (TEMPRA-113, design/handoff/layout-take-4) set the top\n * bar, the wider sidebar and the panel, and gave the dot a second, pulsing state. The palette\n * (TEMPRA-1) changes values here and both the app and the site follow. Light and dark come from\n * the system through light-dark(), or from the account's theme on the root (data-theme).\n */\n:root {\n  color-scheme: light dark;\n\n  /* Color: surfaces */\n  --tempra-color-bg: light-dark(#ffffff, #1b1b1d); /* the sheet, panels, pills */\n  --tempra-color-ground: light-dark(#f3f3f1, #121214); /* the page under them, inset fills */\n  --tempra-color-hover: light-dark(#e9e9e6, #222225);\n  --tempra-color-selected: light-dark(#e1e1dd, #2a2a2e);\n  --tempra-color-selection: light-dark(#dededa, #3a3a3d);\n\n  /* Color: text, in three steps */\n  --tempra-color-text: light-dark(#1a1a1b, #ececea);\n  --tempra-color-muted: light-dark(#6f6f73, #9a9a9e);\n  --tempra-color-faint: light-dark(#a3a3a7, #68686c);\n\n  /* Color: lines */\n  --tempra-color-border: light-dark(#e8e8e4, #2a2a2d);\n  --tempra-color-border-strong: light-dark(#d2d2ce, #3c3c40);\n\n  /* Color: an agent's recent change (the only colour before the palette), cooling to grey */\n  --tempra-color-agent: light-dark(#e8722a, #f0884a);\n  --tempra-color-agent-cool: var(--tempra-color-faint);\n\n  /* Color: a dimmed page behind a sheet or a full-screen view */\n  --tempra-color-scrim: light-dark(rgb(20 20 22 / 0.2), rgb(0 0 0 / 0.5));\n\n  /* Color: links are text, underlined in running text (no colour until the palette) */\n  --tempra-color-link: var(--tempra-color-text);\n  --tempra-color-link-visited: var(--tempra-color-text);\n  --tempra-color-code-bg: var(--tempra-color-ground);\n\n  /* Elevation */\n  --tempra-shadow:\n    0 1px 2px light-dark(rgb(0 0 0 / 0.04), rgb(0 0 0 / 0.4)),\n    0 6px 24px light-dark(rgb(0 0 0 / 0.04), rgb(0 0 0 / 0.35));\n\n  /* Type (TEMPRA-108): the serif is the document; everything else is the app's sans.\n     body: all of the app and the site (chrome, view titles, the byline, comments, public pages).\n     reader: a concept's own text only (its title, description and .prose body).\n     mono: code, fences, the Markdown view, paths and hashes. */\n  --tempra-font-body:\n    -apple-system, BlinkMacSystemFont, \"SF Pro Text\", system-ui, \"Segoe UI\", Helvetica, sans-serif;\n  --tempra-font-reader:\n    \"Iowan Old Style\", \"Palatino Linotype\", Charter, Georgia, \"Times New Roman\", serif;\n  --tempra-font-mono: ui-monospace, \"SF Mono\", Menlo, monospace;\n  --tempra-font-size: 14px; /* the app's base text */\n  --tempra-measure: 680px; /* the reader's column, with its padding */\n  --tempra-measure-reader: 34em; /* concept text: about 66 characters of the reader's serif */\n\n  /* Type scale: the only pixel sizes in the CSS (inside .prose, sizes are em of the reading size) */\n  --tempra-text-initial: 9px; /* an avatar's initials */\n  --tempra-text-label: 11px; /* uppercase labels, marks */\n  --tempra-text-meta: 12px; /* timestamps, crumbs, small print */\n  --tempra-text-ui: 13px; /* controls, panels, the tree, comments */\n  --tempra-text-name: 15px; /* a library's name, dialog heads, the wordmark */\n  --tempra-text-reader: 17px; /* a concept's body and description, the landing page's lede */\n  --tempra-text-h2: 22px; /* a view's title on a phone */\n  --tempra-text-page: 28px; /* a view's title (h1); a concept's title on a phone */\n  --tempra-text-title: 36px; /* a concept's title */\n\n  /* Weights: three */\n  --tempra-weight-regular: 400; /* text */\n  --tempra-weight-medium: 500; /* names in rows, a concept's title, the body's h1 and h2 */\n  --tempra-weight-strong: 600; /* the sans's headings, section labels, the wordmark */\n\n  /* Leading: three */\n  --tempra-leading-tight: 1.2; /* titles and headings */\n  --tempra-line-height: 1.5; /* the app's text */\n  --tempra-leading-reader: 1.65; /* reading */\n\n  /* Space */\n  --tempra-space-1: 0.25rem;\n  --tempra-space-2: 0.5rem;\n  --tempra-space-3: 1rem;\n  --tempra-space-4: 2rem;\n  --tempra-gutter: 8px; /* the frame's gutter */\n  --tempra-sheet-pad: 40px; /* a page's side padding in the sheet */\n\n  /* The frame (take 4): a top bar across the window, the sidebar, one panel beside a concept.\n     The breakpoints are 1100px (the panel overlays the page) and 900px (the phone layout); a\n     media query cannot read a token, so they are written where they are used. */\n  --tempra-topbar: 60px; /* the top bar */\n  --tempra-sidebar: 264px; /* the sidebar's width, and the phone drawer's */\n  --tempra-panel: 360px; /* a concept's panel (Comments, History, Properties) */\n  --tempra-bar: 52px; /* the phone's top bar */\n  --tempra-row: 30px; /* a sidebar row */\n  --tempra-touch: 44px; /* the least touch target on a phone */\n  --tempra-avatar: 22px;\n  --tempra-avatar-small: 20px;\n  --tempra-dot: 6px; /* an agent's change, a reader's unverified state */\n\n  /* A concept's columns: contents on the left, the text, comments on the right */\n  --tempra-column-text: 620px;\n  --tempra-margin-contents: 180px;\n  --tempra-margin-comments: 290px;\n  --tempra-margin-gap: 48px;\n  --tempra-page-width: 760px; /* home, Needs you, Activity, a folder */\n\n  /* Shape: squarer than take 2 */\n  --tempra-radius: 5px; /* code */\n  --tempra-radius-mark: 3px;\n  --tempra-radius-row: 7px; /* sidebar rows, inputs */\n  --tempra-radius-box: 10px; /* cards, list boxes, threads */\n  --tempra-radius-card: 10px; /* the sheet, dialogs */\n  --tempra-radius-tile: 6px; /* the library's initial */\n  --tempra-radius-pill: 999px;\n\n  /* Motion: the pulse of the change dot while an agent writes */\n  --tempra-pulse: 1.6s;\n}\n\n/* The account's theme (take 4): the shell puts it on the root; the tokens above follow. */\n:root[data-theme=\"light\"] {\n  color-scheme: light;\n}\n\n:root[data-theme=\"dark\"] {\n  color-scheme: dark;\n}\n\n/* Element defaults for every page of the app and the site; values come from tokens.css. */\n*,\n*::before,\n*::after {\n  box-sizing: border-box;\n}\n\nbody {\n  margin: 0;\n  padding: var(--tempra-space-3);\n  background: var(--tempra-color-bg);\n  color: var(--tempra-color-text);\n  font-family: var(--tempra-font-body);\n  font-size: var(--tempra-font-size);\n  line-height: var(--tempra-line-height);\n  -webkit-font-smoothing: antialiased;\n}\n\n::selection {\n  background: var(--tempra-color-selection);\n}\n\nh1 {\n  margin: 0 0 var(--tempra-space-3);\n  font-size: var(--tempra-text-page);\n  font-weight: var(--tempra-weight-medium);\n  line-height: var(--tempra-leading-tight);\n  letter-spacing: -0.02em;\n}\n\nh2 {\n  margin: var(--tempra-space-4) 0 var(--tempra-space-2);\n  font-size: var(--tempra-font-size);\n  font-weight: var(--tempra-weight-strong);\n}\n\nh3 {\n  font-size: var(--tempra-text-ui);\n  font-weight: var(--tempra-weight-strong);\n}\n\na {\n  color: var(--tempra-color-link);\n  text-decoration: underline;\n  text-decoration-color: var(--tempra-color-border-strong);\n  text-underline-offset: 2px;\n}\n\na:visited {\n  color: var(--tempra-color-link-visited);\n}\n\na:hover {\n  text-decoration-color: currentcolor;\n}\n\n:focus-visible {\n  outline: 2px solid var(--tempra-color-text);\n  outline-offset: 2px;\n}\n\n/* A text field shows focus by its caret and a firmer edge, not the ring. */\ninput:not([type=\"checkbox\"], [type=\"radio\"], [type=\"file\"]):focus-visible,\nselect:focus-visible,\ntextarea:focus-visible {\n  outline: 1px solid var(--tempra-color-border-strong);\n  outline-offset: 0;\n  border-color: var(--tempra-color-border-strong);\n}\n\ncode,\npre,\nkbd,\nsamp {\n  font-family: var(--tempra-font-mono);\n}\n\ncode {\n  font-size: 0.92em;\n}\n\n/* A block of code or a command never widens the page: it scrolls on its own. */\npre {\n  max-width: 100%;\n  overflow-x: auto;\n}\n\nkbd {\n  padding: 1px 7px;\n  border-radius: var(--tempra-radius-pill);\n  background: var(--tempra-color-ground);\n  color: var(--tempra-color-faint);\n  font-family: inherit;\n  font-size: var(--tempra-text-label);\n}\n\nhr {\n  border: 0;\n  border-top: 1px solid var(--tempra-color-border);\n}\n\n/* Controls: pills. A plain button is outlined; .primary is the one solid action; .ghost is text.\n   A link that acts as a button (Review, Back to current) takes .button and looks the same. */\nbutton,\ninput,\nselect,\ntextarea {\n  font: inherit;\n  color: inherit;\n}\n\nbutton,\na.button {\n  padding: 5px 12px;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-pill);\n  background: var(--tempra-color-bg);\n  font-size: var(--tempra-text-ui);\n  white-space: nowrap;\n  cursor: pointer;\n}\n\na.button {\n  display: inline-block;\n  color: var(--tempra-color-text);\n  line-height: var(--tempra-line-height);\n  text-decoration: none;\n}\n\nbutton:hover:not(:disabled),\na.button:hover {\n  background: var(--tempra-color-hover);\n  color: var(--tempra-color-text);\n}\n\nbutton:disabled {\n  cursor: default;\n  opacity: 0.5;\n}\n\nbutton.primary,\na.button.primary {\n  border-color: var(--tempra-color-text);\n  background: var(--tempra-color-text);\n  color: var(--tempra-color-bg);\n  font-weight: var(--tempra-weight-medium);\n}\n\nbutton.primary:hover:not(:disabled),\na.button.primary:hover {\n  background: var(--tempra-color-text);\n  opacity: 0.85;\n}\n\n/* A text-only button: a link's look, a button's job. */\nbutton.ghost {\n  border-color: transparent;\n  background: transparent;\n  color: var(--tempra-color-muted);\n}\n\ninput:not([type=\"checkbox\"], [type=\"radio\"], [type=\"file\"]),\nselect,\ntextarea {\n  max-width: 100%;\n  padding: 5px 10px;\n  border: 1px solid var(--tempra-color-border-strong);\n  border-radius: var(--tempra-radius-row);\n  background: var(--tempra-color-bg);\n  font-size: var(--tempra-text-ui);\n}\n\ntextarea {\n  line-height: var(--tempra-line-height);\n}\n\nfieldset {\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-box);\n}\n\n/* A form as a column: a label over each field, choices on their own lines, actions last. */\nform.stack fieldset {\n  margin: 0 0 20px;\n  padding: 0;\n  border: 0;\n}\n\nform.stack legend {\n  margin-bottom: 6px;\n  padding: 0;\n  font-weight: var(--tempra-weight-medium);\n}\n\n.field {\n  display: block;\n  margin: 10px 0;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-ui);\n}\n\n.field input,\n.field select {\n  display: block;\n  width: 100%;\n  max-width: 22rem;\n  margin-top: 4px;\n  color: var(--tempra-color-text);\n  font-size: var(--tempra-font-size);\n}\n\n.choice {\n  display: flex;\n  align-items: baseline;\n  gap: 8px;\n  margin: 4px 0;\n}\n\n.indent {\n  margin: 2px 0 6px 24px;\n}\n\n.actions {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  margin-top: 8px;\n}\n\ntable {\n  border-collapse: collapse;\n}\n\nth,\ntd {\n  padding: var(--tempra-space-1) var(--tempra-space-2);\n  text-align: left;\n  vertical-align: top;\n}\n\nimg {\n  max-width: 100%;\n}\n\ndetails > summary {\n  cursor: pointer;\n}\n\n/* Text roles used across pages. */\n.muted {\n  color: var(--tempra-color-muted);\n}\n\n.faint {\n  color: var(--tempra-color-faint);\n}\n\n.small {\n  font-size: var(--tempra-text-meta);\n}\n\n.warn {\n  font-weight: var(--tempra-weight-medium);\n}\n\n/* An uppercase label over a group (SOURCES, LINKED FROM). */\n.label {\n  margin: 0 0 var(--tempra-space-2);\n  color: var(--tempra-color-faint);\n  font-size: var(--tempra-text-label);\n  font-weight: var(--tempra-weight-regular);\n  letter-spacing: 0.04em;\n  text-transform: uppercase;\n}\n\n/* A message about the page (saved, an error, a version in the past). */\n.notice {\n  margin: var(--tempra-space-2) 0;\n  padding: 10px 12px;\n  border-radius: var(--tempra-radius-box);\n  background: var(--tempra-color-ground);\n  font-size: var(--tempra-text-ui);\n}\n\n/* A row of short labels (type, trust tier, status): kept apart, wrapping on narrow screens. */\n.chips {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: var(--tempra-space-1) var(--tempra-space-2);\n}\n\n.chip {\n  display: inline-block;\n  padding: 1px 7px;\n  border: 1px solid transparent;\n  border-radius: var(--tempra-radius-pill);\n  background: var(--tempra-color-ground);\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-label);\n  white-space: nowrap;\n}\n\n/* Something to act on: in the text colour (no colour until the palette). */\n.chip.warn,\n.chip.bad {\n  color: var(--tempra-color-text);\n}\n\n/* Text for screen readers only: what a symbol (a mark, an icon) means. */\n.visually-hidden {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  overflow: hidden;\n  clip-path: inset(50%);\n  white-space: nowrap;\n}\n\n/*\n * How a rendered concept reads (tempra-dev: app/reader, Reading typography): the body of a\n * concept, in the app now and wherever concepts are shown later (the site, inline MCP Apps views).\n * Scoped to .prose. A serif at 17px, about 66 characters to the line, spacing in em so the rhythm\n * scales with the text. Greys, type, spacing and rules only until the palette (TEMPRA-1).\n */\n.prose {\n  max-width: var(--tempra-measure-reader);\n  color: var(--tempra-color-text);\n  font-family: var(--tempra-font-reader);\n  font-size: var(--tempra-text-reader);\n  line-height: var(--tempra-leading-reader);\n  font-kerning: normal;\n  font-optical-sizing: auto;\n  font-variant-ligatures: common-ligatures;\n  /* Figures that sit in running text; tables and markers switch to lining, tabular ones. */\n  font-variant-numeric: oldstyle-nums proportional-nums;\n  /* Quotes and stops hang into the margin where the browser can (Safari). */\n  hanging-punctuation: first allow-end;\n  /* A long URL or identifier wraps rather than pushing the column wider; words never break. */\n  overflow-wrap: break-word;\n  hyphens: manual;\n  text-size-adjust: 100%;\n}\n\n.prose > :first-child,\n.prose > [hidden]:first-child + * {\n  margin-top: 0;\n}\n\n.prose > :last-child {\n  margin-bottom: 0;\n}\n\n/* Vertical rhythm: one step between blocks, in em. */\n.prose p,\n.prose ul,\n.prose ol,\n.prose blockquote,\n.prose pre,\n.prose .table {\n  margin: 0 0 1.1em;\n}\n\n/* No line ends on a lone short word; headings are balanced across their lines. */\n.prose p,\n.prose li,\n.prose blockquote {\n  text-wrap: pretty;\n}\n\n.prose strong {\n  font-weight: var(--tempra-weight-strong);\n}\n\n.prose s {\n  color: var(--tempra-color-muted);\n}\n\n/* Headings: more space above than below, so each sits with what it introduces. */\n.prose h1,\n.prose h2,\n.prose h3,\n.prose h4,\n.prose h5,\n.prose h6 {\n  margin: 1.9em 0 0.5em;\n  font-family: var(--tempra-font-reader);\n  font-variant-numeric: lining-nums proportional-nums;\n  line-height: var(--tempra-leading-tight);\n  letter-spacing: -0.005em;\n  text-wrap: balance;\n  break-after: avoid;\n  /* Clear of the cluster when a contents link scrolls to it. */\n  scroll-margin-top: 72px;\n}\n\n.prose h1 {\n  font-size: 1.65em;\n  font-weight: var(--tempra-weight-medium);\n  letter-spacing: -0.012em;\n}\n\n.prose h2 {\n  font-size: 1.35em;\n  font-weight: var(--tempra-weight-medium);\n  letter-spacing: -0.01em;\n}\n\n.prose h3 {\n  font-size: 1.12em;\n  font-weight: var(--tempra-weight-strong);\n}\n\n.prose h4,\n.prose h5,\n.prose h6 {\n  margin-top: 1.6em;\n  font-size: 1em;\n  font-weight: var(--tempra-weight-strong);\n  font-variant-caps: all-small-caps;\n  letter-spacing: 0.04em;\n}\n\n.prose h5,\n.prose h6 {\n  color: var(--tempra-color-muted);\n}\n\n/* A heading straight after another needs less room. */\n.prose :is(h1, h2, h3, h4, h5, h6) + :is(h2, h3, h4, h5, h6) {\n  margin-top: 0.7em;\n}\n\n/* Links: text-coloured, a thin underline at partial strength that firms up on hover. */\n.prose a {\n  color: inherit;\n  text-decoration-line: underline;\n  text-decoration-thickness: 1px;\n  text-decoration-color: color-mix(in srgb, currentColor 38%, transparent);\n  text-underline-offset: 0.18em;\n  text-decoration-skip-ink: auto;\n}\n\n.prose a:hover {\n  text-decoration-color: currentColor;\n}\n\n/* A link the reader would not follow (an unsafe scheme) reads as text. */\n.prose a:not([href]) {\n  text-decoration: none;\n}\n\n.prose a.broken {\n  color: var(--tempra-color-muted);\n  text-decoration-line: line-through;\n  text-decoration-color: currentColor;\n}\n\n/* Lists: muted markers, figures that line up; tight lists close, loose ones like paragraphs. */\n.prose ul,\n.prose ol {\n  padding-left: 1.4em;\n}\n\n.prose li {\n  margin: 0.2em 0;\n}\n\n.prose li::marker {\n  color: var(--tempra-color-muted);\n  font-variant-numeric: lining-nums tabular-nums;\n}\n\n.prose li > p {\n  margin: 0;\n}\n\n.prose li > :is(ul, ol) {\n  margin: 0.2em 0 0;\n}\n\n.prose :is(ul, ol).loose > li {\n  margin: 0.55em 0;\n}\n\n.prose :is(ul, ol).loose > li > p + * {\n  margin-top: 0.55em;\n}\n\n.prose .tasks {\n  padding-left: 0.1em;\n  list-style: none;\n}\n\n.prose li.task {\n  display: grid;\n  grid-template-columns: auto 1fr;\n  column-gap: 0.55em;\n  align-items: baseline;\n}\n\n.prose li.task > :not(input) {\n  grid-column: 2;\n}\n\n.prose li.task > input {\n  margin: 0;\n  accent-color: var(--tempra-color-text);\n}\n\n/* Blockquotes upright: long italic passages read slowly. */\n.prose blockquote {\n  margin-left: 0;\n  margin-right: 0;\n  padding: 0 0 0 1.1em;\n  border-left: 2px solid var(--tempra-color-border-strong);\n  color: var(--tempra-color-muted);\n}\n\n.prose blockquote > :last-child {\n  margin-bottom: 0;\n}\n\n/* Code: the mono a step down, no ligatures; inline on the code grey, blocks scroll sideways. */\n.prose code {\n  padding: 0.1em 0.35em;\n  border-radius: var(--tempra-radius);\n  background: var(--tempra-color-code-bg);\n  font-family: var(--tempra-font-mono);\n  font-size: 0.86em;\n  font-variant-ligatures: none;\n  font-variant-numeric: normal;\n  box-decoration-break: clone;\n  -webkit-box-decoration-break: clone;\n}\n\n.prose pre {\n  position: relative;\n  overflow-x: auto;\n  overscroll-behavior-x: contain;\n  padding: 14px 18px;\n  border-radius: var(--tempra-radius-row);\n  background: var(--tempra-color-code-bg);\n  font-family: var(--tempra-font-mono);\n  font-size: 0.8em;\n  font-variant-ligatures: none;\n  line-height: var(--tempra-line-height);\n  tab-size: 2;\n  white-space: pre;\n  overflow-wrap: normal;\n}\n\n.prose pre code {\n  padding: 0;\n  border-radius: 0;\n  background: none;\n  font-size: inherit;\n}\n\n/* The fence's language, quietly above the code (generated content: not part of the text). */\n.prose pre[data-lang] {\n  padding-top: 32px;\n}\n\n.prose pre[data-lang]::before {\n  content: attr(data-lang);\n  position: absolute;\n  top: 10px;\n  left: 18px;\n  color: var(--tempra-color-faint);\n  font-family: var(--tempra-font-body);\n  font-size: var(--tempra-text-label);\n  letter-spacing: 0.04em;\n  text-transform: lowercase;\n}\n\n/* What the reader shows as its markdown (raw HTML, reference links): quieter than code. */\n.prose pre.raw,\n.prose code.raw {\n  color: var(--tempra-color-muted);\n}\n\n/*\n * Tables: real tables in their own scroll container, so a wide one scrolls sideways (on a phone\n * too) instead of breaking words. A table fills the column in a hairline box, with a light header\n * row on the ground grey and rules between rows, none between columns (take 3, Figures).\n */\n.prose .table {\n  max-width: 100%;\n  overflow-x: auto;\n  overscroll-behavior-x: contain;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-box);\n}\n\n.prose table {\n  width: 100%;\n  border-collapse: collapse;\n  font-family: var(--tempra-font-body);\n  font-size: 0.82em;\n  font-variant-numeric: lining-nums tabular-nums;\n  line-height: var(--tempra-line-height);\n}\n\n.prose th,\n.prose td {\n  padding: 0.6em 0.9em;\n  border: 0;\n  border-bottom: 1px solid var(--tempra-color-border);\n  text-align: left;\n  vertical-align: top;\n  overflow-wrap: normal;\n  word-break: normal;\n  text-wrap: pretty;\n}\n\n.prose tbody tr:last-child td {\n  border-bottom: 0;\n}\n\n.prose th {\n  background: var(--tempra-color-ground);\n  font-weight: var(--tempra-weight-medium);\n  vertical-align: bottom;\n}\n\n.prose td code,\n.prose th code {\n  background: none;\n  padding: 0;\n}\n\n.prose [data-align=\"center\"] {\n  text-align: center;\n}\n\n.prose [data-align=\"right\"] {\n  text-align: right;\n}\n\n.prose hr {\n  margin: 2.2em 0;\n  border: 0;\n  border-top: 1px solid var(--tempra-color-border);\n}\n\n/* An image in running text stays in the line, no taller than the column is wide. */\n.prose img {\n  max-width: 100%;\n  height: auto;\n  vertical-align: middle;\n}\n\n.prose .image-dropped,\n.prose .image-broken {\n  color: var(--tempra-color-faint);\n  font-style: italic;\n}\n\n.prose .image-broken {\n  padding: 0 0.3em;\n  border: 1px dashed var(--tempra-color-border-strong);\n  border-radius: var(--tempra-radius);\n}\n\n/*\n * Figures (take 3, Figures): an image alone in its paragraph, or a diagram, with a caption\n * beneath: \"Figure n.\" a step darker, then the image's title or alt text, in the UI face.\n */\n.prose figure {\n  margin: 1.6em 0;\n}\n\n.prose figure.figure > p {\n  margin: 0;\n}\n\n.prose .figure-media {\n  display: block;\n}\n\n.prose .figure-media img {\n  display: block;\n  max-width: 100%;\n  height: auto;\n  border-radius: var(--tempra-radius-box);\n}\n\n/* The image is the button that enlarges it: no button look, a focus ring when reached by keys. */\n.prose .figure-open {\n  display: block;\n  max-width: 100%;\n  padding: 0;\n  border: 0;\n  border-radius: var(--tempra-radius-box);\n  background: none;\n  cursor: zoom-in;\n}\n\n.prose .figure-open:hover:not(:disabled) {\n  background: none;\n}\n\n.prose .figure-open:focus-visible {\n  outline: 2px solid var(--tempra-color-text);\n  outline-offset: 3px;\n}\n\n.prose figcaption {\n  margin-top: 8px;\n  color: var(--tempra-color-muted);\n  font-family: var(--tempra-font-body);\n  font-size: var(--tempra-text-meta);\n  line-height: var(--tempra-line-height);\n  text-wrap: pretty;\n  user-select: none;\n}\n\n.prose .figure-number {\n  color: var(--tempra-color-text);\n  font-weight: var(--tempra-weight-medium);\n}\n\n/* An image that can't be shown: a dashed box where it would be, saying so, its path and alt. */\n.figure-broken {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  gap: 4px;\n  min-height: 12rem;\n  padding: 24px;\n  border: 1px dashed var(--tempra-color-border-strong);\n  border-radius: var(--tempra-radius-box);\n  background: var(--tempra-color-ground);\n  color: var(--tempra-color-muted);\n  font-family: var(--tempra-font-body);\n  font-size: var(--tempra-text-meta);\n  font-style: normal;\n  line-height: var(--tempra-line-height);\n  text-align: center;\n  overflow-wrap: anywhere;\n}\n\n.figure-broken svg {\n  margin-bottom: 4px;\n  color: var(--tempra-color-faint);\n}\n\n.figure-broken .figure-broken-title {\n  color: var(--tempra-color-text);\n  font-size: var(--tempra-text-ui);\n}\n\n/* Footnote markers: a source's number, small and muted, joined to its word. */\n.prose sup.fnref {\n  margin-left: 0.08em;\n  color: var(--tempra-color-muted);\n  font-size: 0.68em;\n  font-variant-numeric: lining-nums tabular-nums;\n  line-height: 0;\n  vertical-align: super;\n  white-space: nowrap;\n}\n\n.prose sup.fnref a {\n  padding: 0 0.12em;\n  color: inherit;\n  text-decoration: none;\n}\n\n.prose sup.fnref a:hover {\n  text-decoration: underline;\n}\n\n/* Changes since human verification, over the text: lines and greys only. */\n.prose ins.diff-added {\n  text-decoration: underline;\n  text-decoration-thickness: 2px;\n  text-underline-offset: 0.22em;\n}\n\n.prose del.diff-removed {\n  color: var(--tempra-color-faint);\n  text-decoration: line-through;\n}\n\n/*\n * What sits around a concept body in the reader (tempra-dev: app/reader): the hover cards and the\n * selection toolbar (popovers in the top layer, placed by the app through --float-x and\n * --float-y), comment highlights (the CSS Custom Highlight API), the threads in the Comments\n * panel and the stored Markdown view. Lines and greys only (no colour until TEMPRA-1).\n */\n\n/* A popover: placed at the coordinates the app gives it, never where the browser centres one. */\n.floating {\n  position: fixed;\n  inset: auto;\n  top: var(--float-y, 0);\n  left: var(--float-x, 0);\n  margin: 0;\n  padding: 0;\n  border: 0;\n  background: none;\n  color: inherit;\n  overflow: visible;\n}\n\n/* Hover cards over footnote markers and links. */\n.tooltip {\n  max-width: 22rem;\n  padding: 8px 12px;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-box);\n  background: var(--tempra-color-bg);\n  box-shadow: var(--tempra-shadow);\n  color: var(--tempra-color-text);\n  font-family: var(--tempra-font-body);\n  font-size: var(--tempra-text-ui);\n  line-height: var(--tempra-line-height);\n  text-wrap: pretty;\n}\n\n.tooltip p {\n  margin: 0;\n}\n\n.tooltip p + p {\n  margin-top: 0.4em;\n}\n\n/*\n * Comments (TEMPRA-13). A thread's quote is underlined in the body (dotted); the one whose thread\n * is open in the margin is filled grey and underlined solid (take 3); a comment being written\n * fills its text with the selection grey. Drawn as\n * highlights, so the body's DOM never changes for them.\n */\n::highlight(tempra-comment) {\n  text-decoration-line: underline;\n  text-decoration-style: dotted;\n  text-decoration-thickness: 1px;\n  text-underline-offset: 0.22em;\n}\n\n::highlight(tempra-comment-active) {\n  background-color: var(--tempra-color-hover);\n  text-decoration-line: underline;\n  text-decoration-style: solid;\n  text-decoration-thickness: 1px;\n  text-underline-offset: 0.22em;\n}\n\n::highlight(tempra-comment-draft) {\n  background-color: var(--tempra-color-selected);\n}\n\n/* The selection toolbar: a pill above the selected text. */\n.selection-tools > div {\n  display: flex;\n  gap: 2px;\n  padding: 3px;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-pill);\n  background: var(--tempra-color-bg);\n  box-shadow: var(--tempra-shadow);\n  font-family: var(--tempra-font-body);\n}\n\n.selection-tools button {\n  padding: 4px 12px;\n  border: 0;\n  background: var(--tempra-color-text);\n  color: var(--tempra-color-bg);\n  font-size: var(--tempra-text-meta);\n  font-weight: var(--tempra-weight-medium);\n}\n\n.selection-tools button:hover:not(:disabled) {\n  background: var(--tempra-color-text);\n  opacity: 0.85;\n}\n\n/* A footnote's own text in the Sources section and a marker's card. */\n.note > p {\n  margin: 0;\n}\n\n.note > p + * {\n  margin-top: 0.4em;\n}\n\n/*\n * Diagrams (tempra-dev: app/diagrams): Pele's SVG themed through its custom properties, greys only\n * until the palette (TEMPRA-1), so dark mode follows the tokens. Colours an author sets in the\n * diagram are content and stay. In the body it sits in a quiet frame (take 3, Figures) with Source\n * and Enlarge in its corner, and scrolls sideways when it cannot shrink to the column; the\n * full-screen view draws it again with the same theme.\n */\n.prose figure.diagram,\n.lightbox {\n  --pele-bg: var(--tempra-color-bg);\n  --pele-fg: var(--tempra-color-text);\n  --pele-muted: var(--tempra-color-muted);\n  --pele-line: var(--tempra-color-muted);\n  --pele-surface: var(--tempra-color-ground);\n  --pele-surface-alt: var(--tempra-color-hover);\n  --pele-border: var(--tempra-color-border-strong);\n  --pele-accent: var(--tempra-color-text);\n  --pele-font: var(--tempra-font-body);\n  --pele-font-mono: var(--tempra-font-mono);\n  --pele-radius: var(--tempra-radius-row);\n  --pele-series-1: var(--tempra-color-text);\n  --pele-series-2: var(--tempra-color-muted);\n  --pele-series-3: var(--tempra-color-faint);\n  --pele-series-4: var(--tempra-color-border-strong);\n  --pele-series-5: var(--tempra-color-selection);\n  --pele-series-6: var(--tempra-color-selected);\n  --pele-series-7: var(--tempra-color-hover);\n  --pele-series-8: var(--tempra-color-ground);\n}\n\n.prose figure.diagram {\n  margin: 1.6em 0;\n}\n\n.prose .diagram-frame {\n  position: relative;\n  padding: 40px 20px 20px;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-box);\n}\n\n.prose .diagram-svg {\n  overflow-x: auto;\n  overscroll-behavior-x: contain;\n  font-family: var(--tempra-font-body);\n  font-size: var(--tempra-text-ui);\n}\n\n.prose .diagram-svg svg {\n  display: block;\n  max-width: 100%;\n  height: auto;\n  margin: 0 auto;\n}\n\n.prose .diagram-frame pre.diagram-source {\n  margin: 0;\n}\n\n/* Source and Enlarge: small grey pills in the frame's corner. */\n.prose .figure-tools {\n  position: absolute;\n  top: 8px;\n  right: 8px;\n  display: flex;\n  gap: 2px;\n  font-family: var(--tempra-font-body);\n}\n\n.prose .figure-tools button {\n  display: inline-grid;\n  place-items: center;\n  min-width: 24px;\n  height: 24px;\n  padding: 0 10px;\n  border: 0;\n  background: var(--tempra-color-ground);\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-label);\n  line-height: 1;\n}\n\n.prose .figure-tools button:hover:not(:disabled),\n.prose .figure-tools button[aria-pressed=\"true\"] {\n  background: var(--tempra-color-hover);\n  color: var(--tempra-color-text);\n}\n\n.prose .figure-tools .figure-enlarge {\n  padding: 0;\n}\n\n.prose figure.diagram.failed pre {\n  margin: 0;\n}\n\n.prose .diagram-notice {\n  margin: 6px 0 0;\n  color: var(--tempra-color-muted);\n  font-family: var(--tempra-font-body);\n  font-size: var(--tempra-text-meta);\n}\n\n/* On a touch screen the corner controls are full-size targets. */\n@media (pointer: coarse) {\n  .prose .diagram-frame {\n    padding-top: 60px;\n  }\n\n  .prose .figure-tools {\n    top: 6px;\n    right: 6px;\n  }\n\n  .prose .figure-tools button {\n    min-width: var(--tempra-touch);\n    height: var(--tempra-touch);\n    font-size: var(--tempra-text-meta);\n  }\n}\n\n/*\n * The full-screen view of a figure (take 3, Lightbox): a modal dialog over the app on the ground\n * colour. A header (where, \"Figure n of m\", Open original and Download as pills, close), the\n * figure as large as fits between previous and next, and beneath it the caption and a quiet line.\n */\n.lightbox {\n  position: fixed;\n  inset: 0;\n  width: 100%;\n  max-width: none;\n  height: 100%;\n  max-height: none;\n  margin: 0;\n  padding: 0;\n  border: 0;\n  background: var(--tempra-color-ground);\n  color: var(--tempra-color-text);\n  font-family: var(--tempra-font-body);\n  font-size: var(--tempra-text-ui);\n  line-height: var(--tempra-line-height);\n  overflow: hidden;\n}\n\n.lightbox[open] {\n  display: grid;\n  grid-template-rows: auto minmax(0, 1fr) auto;\n}\n\n.lightbox::backdrop {\n  background: var(--tempra-color-ground);\n}\n\n.lightbox-head {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 8px 12px;\n  padding: 16px 20px;\n}\n\n.lightbox-where {\n  color: var(--tempra-color-muted);\n}\n\n.lightbox-where::after {\n  content: \"·\";\n  margin-left: 12px;\n  color: var(--tempra-color-faint);\n}\n\n.lightbox-actions {\n  display: flex;\n  gap: 6px;\n  margin-left: auto;\n}\n\n.lightbox-actions a {\n  display: inline-flex;\n  align-items: center;\n  padding: 6px 14px;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-pill);\n  background: var(--tempra-color-bg);\n  color: var(--tempra-color-text);\n  text-decoration: none;\n  white-space: nowrap;\n}\n\n.lightbox-actions a:hover {\n  background: var(--tempra-color-hover);\n}\n\n.lightbox-round {\n  display: inline-grid;\n  flex: none;\n  place-items: center;\n  width: 34px;\n  height: 34px;\n  padding: 0;\n  border: 1px solid var(--tempra-color-border);\n  background: var(--tempra-color-bg);\n}\n\n.lightbox-stage {\n  display: grid;\n  grid-template-columns: auto minmax(0, 1fr) auto;\n  align-items: center;\n  gap: 16px;\n  min-height: 0;\n  padding: 0 20px;\n}\n\n.lightbox-stage .lightbox-prev,\n.lightbox-stage .lightbox-next {\n  width: var(--tempra-touch);\n  height: var(--tempra-touch);\n}\n\n.lightbox-prev {\n  grid-column: 1;\n}\n\n.lightbox-figure {\n  display: grid;\n  grid-column: 2;\n  place-items: center;\n  width: 100%;\n  height: 100%;\n  min-height: 0;\n}\n\n.lightbox-next {\n  grid-column: 3;\n}\n\n.lightbox-figure > img {\n  display: block;\n  max-width: 100%;\n  max-height: 100%;\n  object-fit: contain;\n  border-radius: var(--tempra-radius-card);\n  box-shadow: var(--tempra-shadow);\n}\n\n.lightbox-figure > .figure-broken {\n  width: min(100%, 32rem);\n}\n\n.lightbox-diagram {\n  box-sizing: border-box;\n  width: 100%;\n  height: 100%;\n  padding: 24px;\n  border-radius: var(--tempra-radius-card);\n  background: var(--tempra-color-bg);\n  box-shadow: var(--tempra-shadow);\n  font-size: var(--tempra-text-ui);\n}\n\n.lightbox-diagram svg {\n  display: block;\n  width: 100%;\n  height: 100%;\n}\n\n.lightbox-source {\n  max-width: 100%;\n  max-height: 100%;\n  margin: 0;\n  padding: 16px 18px;\n  overflow: auto;\n  border-radius: var(--tempra-radius-box);\n  background: var(--tempra-color-bg);\n  font-family: var(--tempra-font-mono);\n  font-size: var(--tempra-text-ui);\n}\n\n.lightbox-foot {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 4px;\n  padding: 18px 20px 26px;\n  text-align: center;\n}\n\n.lightbox-caption {\n  max-width: var(--tempra-measure);\n  margin: 0;\n  font-size: var(--tempra-text-name);\n  text-wrap: pretty;\n}\n\n.lightbox-facts {\n  max-width: var(--tempra-measure);\n  margin: 0;\n  color: var(--tempra-color-faint);\n  font-size: var(--tempra-text-meta);\n  overflow-wrap: anywhere;\n}\n\n.lightbox-facts > span + span::before {\n  content: \" · \";\n}\n\n/* A phone: smaller gutters, 44px targets, no keyboard hint. */\n@media (max-width: 600px) {\n  .lightbox-head {\n    padding: 8px 12px;\n  }\n\n  .lightbox-where {\n    display: none;\n  }\n\n  .lightbox-actions a {\n    min-height: var(--tempra-touch);\n    padding: 0 14px;\n  }\n\n  .lightbox-round {\n    width: var(--tempra-touch);\n    height: var(--tempra-touch);\n  }\n\n  .lightbox-stage {\n    gap: 4px;\n    padding: 0 4px;\n  }\n\n  .lightbox-foot {\n    padding: 12px 16px 20px;\n  }\n\n  .lightbox-hint {\n    display: none;\n  }\n}\n\n/*\n * The app's frame (TEMPRA-19; take 2 in TEMPRA-53, take 3 in TEMPRA-106, take 4 in TEMPRA-113;\n * tempra-dev: app/workspace). A docs-site layout: a top bar across the window, split at the\n * sidebar's edge (the mark, the library switcher and search over the sidebar; the crumbs, the\n * page's tools, the bell and the avatar over the page), a navigation sidebar with a hairline on\n * its right, and the page as a flat column: no ground, no sheet. The sidebar can be hidden; under\n * 900px it is a drawer behind a top bar. Library settings and the account's pages use the same\n * frame with a sidebar of their own. A concept's own layout is in concept.css; the person's views\n * (home, Activity, a folder) in views.css.\n */\nbody:has(> #root),\nbody.ground {\n  padding: 0;\n  background: var(--tempra-color-bg);\n}\n\n/* ---------- Shared pieces: menus, the avatar, icon buttons ---------- */\n\n.header-sep {\n  color: var(--tempra-color-faint);\n}\n\n/* A menu: a button that opens a card of links below it. */\n.menu {\n  position: relative;\n}\n\n.menu-button {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  padding: 4px 8px;\n  border: 0;\n  background: transparent;\n  color: var(--tempra-color-muted);\n}\n\n.menu-button .caret {\n  display: inline-flex;\n  color: var(--tempra-color-faint);\n}\n\n.menu-list {\n  position: absolute;\n  top: calc(100% + 6px);\n  z-index: 20;\n  display: flex;\n  flex-direction: column;\n  gap: 1px;\n  min-width: 13rem;\n  max-height: 70vh;\n  overflow: auto;\n  margin: 0;\n  padding: 6px;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-box);\n  background: var(--tempra-color-bg);\n  box-shadow: var(--tempra-shadow);\n  list-style: none;\n  font-size: var(--tempra-text-ui);\n}\n\n.menu-list.start {\n  left: 0;\n}\n\n.menu-list.end {\n  right: 0;\n}\n\n/* A menu at the foot of the sidebar opens upwards. */\n.menu-list.up {\n  top: auto;\n  bottom: calc(100% + 6px);\n}\n\n.menu-list a,\n.menu-list button {\n  display: block;\n  width: 100%;\n  padding: 6px 10px;\n  border: 0;\n  border-radius: var(--tempra-radius-row);\n  background: none;\n  color: var(--tempra-color-text);\n  font-size: var(--tempra-text-ui);\n  text-align: left;\n  text-decoration: none;\n}\n\n.menu-list a:hover,\n.menu-list button:hover:not(:disabled),\n.menu-list a[aria-current=\"page\"] {\n  background: var(--tempra-color-hover);\n}\n\n.menu-list .menu-note {\n  padding: 6px 10px 2px;\n  color: var(--tempra-color-faint);\n  font-size: var(--tempra-text-label);\n  letter-spacing: 0.04em;\n  text-transform: uppercase;\n}\n\n/* Who is signed in, at the top of the avatar's menu. */\n.menu-list .menu-who {\n  padding: 6px 10px 4px;\n  color: var(--tempra-color-faint);\n  font-size: var(--tempra-text-meta);\n  overflow-wrap: anywhere;\n}\n\n.menu-list hr {\n  width: 100%;\n  margin: 4px 0;\n}\n\n.avatar {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  width: 26px;\n  height: 26px;\n  padding: 0;\n  border: 0;\n  border-radius: 50%;\n  background: var(--tempra-color-selected);\n  color: var(--tempra-color-text);\n  font-size: var(--tempra-text-initial);\n  font-weight: var(--tempra-weight-strong);\n}\n\n/* A round button holding one 16px glyph. */\n.icon-button {\n  position: relative;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  width: 30px;\n  height: 30px;\n  padding: 0;\n  border: 0;\n  background: transparent;\n  color: var(--tempra-color-muted);\n}\n\n.icon-button[aria-pressed=\"true\"],\n.icon-button[aria-pressed=\"true\"]:hover:not(:disabled) {\n  background: var(--tempra-color-text);\n  color: var(--tempra-color-bg);\n}\n\n.icon-button svg {\n  display: block;\n}\n\n.icon-button:hover:not(:disabled) {\n  color: var(--tempra-color-text);\n}\n\n/* A button with a glyph and a short word or count beside it (the comments toggle). */\n.icon-button.with-count {\n  gap: 6px;\n  width: auto;\n  padding: 0 10px;\n  border-radius: var(--tempra-radius-row);\n  font-size: var(--tempra-text-meta);\n  font-variant-numeric: tabular-nums;\n}\n\n.icon-button.with-count[aria-pressed=\"true\"],\n.icon-button.with-count[aria-pressed=\"true\"]:hover:not(:disabled) {\n  background: var(--tempra-color-selected);\n  color: var(--tempra-color-text);\n}\n\n/* An agent's change: a small dot, warm while fresh, grey once it cools (the one colour). */\n.change-dot {\n  display: inline-block;\n  width: var(--tempra-dot);\n  height: var(--tempra-dot);\n  border-radius: 50%;\n  background: var(--tempra-color-agent-cool);\n  vertical-align: middle;\n}\n\n.change-dot.warm {\n  background: var(--tempra-color-agent);\n}\n\n/* Someone's initials in a small round mark: a person on a light fill, an agent on ink. */\n.avatar-mark {\n  display: inline-grid;\n  flex: none;\n  place-items: center;\n  width: var(--tempra-avatar);\n  height: var(--tempra-avatar);\n  border-radius: 50%;\n  background: var(--tempra-color-selected);\n  color: var(--tempra-color-text);\n  font-size: var(--tempra-text-initial);\n  font-weight: var(--tempra-weight-strong);\n  line-height: 1;\n}\n\n.avatar-mark.agent {\n  background: var(--tempra-color-text);\n  color: var(--tempra-color-bg);\n}\n\n/* A dialog (a concept's properties, its agent notes, all its versions): a card in the top layer. */\n.dialog {\n  width: min(32rem, calc(100vw - 32px));\n  max-height: min(80dvh, 44rem);\n  padding: 0;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-card);\n  background: var(--tempra-color-bg);\n  box-shadow: var(--tempra-shadow);\n  color: var(--tempra-color-text);\n}\n\n.dialog.wide {\n  width: min(40rem, calc(100vw - 32px));\n}\n\n.dialog::backdrop {\n  background: var(--tempra-color-scrim);\n}\n\n.dialog-head {\n  position: sticky;\n  top: 0;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px;\n  padding: 10px 10px 6px 18px;\n  background: var(--tempra-color-bg);\n}\n\n.dialog-head h2 {\n  margin: 0;\n  font-size: var(--tempra-text-name);\n  font-weight: var(--tempra-weight-strong);\n}\n\n.dialog-body {\n  padding: 4px 18px 18px;\n  font-size: var(--tempra-text-ui);\n}\n\n.dialog-foot {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 12px;\n  margin: 12px 0 0;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n}\n\n.dialog-foot a {\n  color: inherit;\n}\n\n/* ---------- A page's column: the account's pages, settings, the library's tools ---------- */\n\n/* One centred column; the frame's top bar and sidebar are around it. */\n.sheet-page,\n.page {\n  width: 100%;\n  max-width: var(--tempra-page-width);\n  margin: 0 auto;\n  padding: 72px var(--tempra-sheet-pad) 96px;\n}\n\n.sheet-page.wide {\n  max-width: 960px;\n}\n\n.page-head {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: baseline;\n  justify-content: space-between;\n  gap: 16px;\n  margin-bottom: 28px;\n}\n\n.page-head h1 {\n  margin: 0;\n}\n\n/* The New pill: an outlined pill with a plus. */\n.pill-button {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  padding: 6px 12px 6px 8px;\n}\n\n.page-foot {\n  margin: 32px 0 0;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-ui);\n}\n\n.page-foot a {\n  color: inherit;\n}\n\n/* The library list (take 4, board 01): cards under Yours and Shared with you. Each card has a\n   quiet cover (the library's tile; an agent's latest change at the right), then its name, what\n   is for the person there, its description and one line of facts. */\n.lib-cards {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));\n  gap: 16px;\n  margin: 0 0 var(--tempra-space-4);\n  padding: 0;\n  list-style: none;\n}\n\n.lib-card {\n  display: flex;\n  flex-direction: column;\n  min-width: 0;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-box);\n  color: var(--tempra-color-text);\n  text-decoration: none;\n  overflow: hidden;\n}\n\n.lib-card:visited {\n  color: var(--tempra-color-text);\n}\n\n.lib-card:hover {\n  border-color: var(--tempra-color-border-strong);\n}\n\n.lib-card-cover {\n  display: flex;\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: 8px;\n  min-height: 112px;\n  padding: 16px;\n  background: var(--tempra-color-ground);\n}\n\n.lib-card-cover .lib-tile {\n  width: 28px;\n  height: 28px;\n}\n\n.lib-card-live {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n}\n\n.lib-card-body {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  padding: 14px 16px 16px;\n}\n\n.lib-card-name {\n  display: flex;\n  align-items: baseline;\n  justify-content: space-between;\n  gap: 8px;\n  font-size: var(--tempra-text-name);\n  font-weight: var(--tempra-weight-medium);\n}\n\n.lib-card-name .owner {\n  color: var(--tempra-color-faint);\n  font-weight: var(--tempra-weight-regular);\n}\n\n.lib-card-for {\n  flex: none;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n  font-weight: var(--tempra-weight-regular);\n}\n\n.lib-card-desc {\n  margin: 0;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-ui);\n}\n\n.lib-card-meta {\n  margin: 4px 0 0;\n  color: var(--tempra-color-faint);\n  font-size: var(--tempra-text-meta);\n}\n\n/* A section of the list (Yours, Shared with you). */\n.lib-section-title {\n  margin: 0 0 12px;\n  font-size: var(--tempra-text-reader);\n  font-weight: var(--tempra-weight-strong);\n}\n\n/* ---------- The workspace: the top bar, the sidebar, the page ---------- */\n\n.workspace {\n  display: grid;\n  grid-template-columns: var(--tempra-sidebar) minmax(0, 1fr);\n  grid-template-rows: var(--tempra-topbar) minmax(0, 1fr);\n  grid-template-areas:\n    \"topbar topbar\"\n    \"sidebar main\";\n  height: 100dvh;\n}\n\n.workspace.sidebar-hidden {\n  grid-template-columns: minmax(0, 1fr);\n  grid-template-areas:\n    \"topbar\"\n    \"main\";\n}\n\n/* The top bar: across the whole window, a hairline under it, split at the sidebar's edge. */\n.ws-topbar {\n  grid-area: topbar;\n  display: grid;\n  grid-template-columns: var(--tempra-sidebar) minmax(0, 1fr);\n  min-width: 0;\n  border-bottom: 1px solid var(--tempra-color-border);\n  background: var(--tempra-color-bg);\n}\n\n.sidebar-hidden .ws-topbar {\n  grid-template-columns: auto minmax(0, 1fr);\n}\n\n/* Over the sidebar: the mark, the library switcher (or the frame's name), search. */\n.topbar-brand {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  min-width: 0;\n  padding: 0 12px 0 16px;\n  border-right: 1px solid var(--tempra-color-border);\n}\n\n.topbar-brand .lib-tile {\n  width: 28px;\n  height: 28px;\n}\n\n/* A hairline between the mark and the name. */\n.topbar-brand .brand-sep {\n  width: 1px;\n  height: 20px;\n  margin: 0 2px;\n  background: var(--tempra-color-border);\n}\n\n/* The frame's name where there is no library to switch: Tempra, Settings, Library settings. */\n.topbar-name {\n  flex: 1;\n  min-width: 0;\n  overflow: hidden;\n  color: var(--tempra-color-text);\n  font-size: var(--tempra-text-name);\n  font-weight: var(--tempra-weight-strong);\n  text-decoration: none;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.topbar-name:visited {\n  color: var(--tempra-color-text);\n}\n\n/* The library switcher: the library's name and a chevron, in a quiet pill. */\n.lib-switch {\n  display: flex;\n  flex: 1;\n  align-items: center;\n  gap: 6px;\n  min-width: 0;\n  padding: 6px 8px;\n  border: 0;\n  border-radius: var(--tempra-radius-row);\n  background: transparent;\n  color: var(--tempra-color-text);\n  font-size: var(--tempra-text-name);\n  font-weight: var(--tempra-weight-strong);\n  text-align: left;\n}\n\n.lib-switch:hover:not(:disabled),\n.lib-switch[aria-expanded=\"true\"] {\n  background: var(--tempra-color-hover);\n}\n\n.lib-switch .lib-name {\n  flex: 1;\n  min-width: 0;\n}\n\n.lib-switch svg {\n  flex: none;\n  color: var(--tempra-color-faint);\n}\n\n/* The round search button, at the brand's right. */\n.search-button {\n  flex: none;\n  width: 36px;\n  height: 36px;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: 50%;\n  background: var(--tempra-color-bg);\n}\n\n/* Over the page: the way back to the sidebar when it is hidden, the crumbs, then the page's\n   tools, the bell and the avatar. */\n.topbar-page {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  min-width: 0;\n  padding: 0 16px 0 20px;\n}\n\n.topbar-crumbs {\n  display: flex;\n  flex: 1;\n  align-items: center;\n  gap: 8px;\n  min-width: 0;\n}\n\n/* The page's tools (a concept's Comments, Copy page and ⋯), from the page itself. */\n.topbar-tools {\n  display: flex;\n  flex: none;\n  align-items: center;\n  gap: 6px;\n}\n\n.topbar-tools:empty {\n  display: none;\n}\n\n.topbar-end {\n  display: flex;\n  flex: none;\n  align-items: center;\n  gap: 6px;\n}\n\n/* The crumbs in the top bar: the folders, then the page, in the app's text size. */\n.crumbs {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  min-width: 0;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-font-size);\n}\n\n.crumbs a {\n  color: inherit;\n  text-decoration: none;\n}\n\n.crumbs a:hover {\n  color: var(--tempra-color-text);\n}\n\n.crumbs .here {\n  color: var(--tempra-color-text);\n  font-weight: var(--tempra-weight-medium);\n}\n\n/* A control in the top bar that reads as a pill: Comments n, Copy page. */\n.topbar-tools .icon-button.with-count,\n.tool-pill {\n  height: 36px;\n  padding: 0 14px;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-pill);\n  background: var(--tempra-color-bg);\n  color: var(--tempra-color-text);\n  font-size: var(--tempra-text-ui);\n}\n\n.tool-pill {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n}\n\n.topbar-tools .icon-button:not(.with-count),\n.topbar-end .icon-button {\n  width: 36px;\n  height: 36px;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: 50%;\n  color: var(--tempra-color-text);\n}\n\n.topbar-tools .icon-button.with-count[aria-pressed=\"true\"],\n.topbar-tools .icon-button.with-count[aria-pressed=\"true\"]:hover:not(:disabled) {\n  background: var(--tempra-color-selected);\n  color: var(--tempra-color-text);\n}\n\n/* The bell: the Inbox and its unread count as a small badge on the button's corner. */\n.bell .badge {\n  position: absolute;\n  top: -4px;\n  right: -4px;\n  display: grid;\n  place-items: center;\n  min-width: 16px;\n  height: 16px;\n  padding: 0 4px;\n  border-radius: var(--tempra-radius-pill);\n  background: var(--tempra-color-text);\n  color: var(--tempra-color-bg);\n  font-size: var(--tempra-text-initial);\n  font-weight: var(--tempra-weight-strong);\n  line-height: 1;\n}\n\n/* The bell's popover: the latest few items, Mark all read above, Open inbox below. */\n.bell-pop {\n  width: min(360px, calc(100vw - 32px));\n  padding: 0;\n}\n\n.bell-pop-head {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px;\n  padding: 12px 16px 10px;\n  border-bottom: 1px solid var(--tempra-color-border);\n  font-size: var(--tempra-text-name);\n  font-weight: var(--tempra-weight-strong);\n}\n\n.bell-pop-head button {\n  padding: 0;\n  border: 0;\n  background: none;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-ui);\n  font-weight: var(--tempra-weight-regular);\n}\n\n.bell-pop-head button:hover:not(:disabled) {\n  color: var(--tempra-color-text);\n}\n\n.menu-list .bell-item {\n  display: grid;\n  grid-template-columns: 20px minmax(0, 1fr) auto;\n  gap: 2px 10px;\n  padding: 10px 16px;\n  border-bottom: 1px solid var(--tempra-color-border);\n  border-radius: 0;\n}\n\n.bell-item .lib-tile {\n  grid-row: span 2;\n  width: 20px;\n  height: 20px;\n  font-size: var(--tempra-text-label);\n}\n\n.bell-item-what {\n  color: var(--tempra-color-text);\n  font-size: var(--tempra-text-ui);\n}\n\n.bell-item-what strong {\n  font-weight: var(--tempra-weight-medium);\n}\n\n.bell-item-where {\n  grid-column: 2;\n  color: var(--tempra-color-faint);\n  font-size: var(--tempra-text-meta);\n}\n\n.bell-item .unread-dot {\n  grid-column: 3;\n  grid-row: span 2;\n  align-self: center;\n  width: var(--tempra-dot);\n  height: var(--tempra-dot);\n  border-radius: 50%;\n  background: var(--tempra-color-text);\n}\n\n.menu-list .bell-foot {\n  padding: 10px 16px;\n  border-radius: 0;\n  color: var(--tempra-color-muted);\n  text-align: center;\n}\n\n.menu-list .bell-empty {\n  padding: 24px 16px;\n  color: var(--tempra-color-muted);\n  text-align: center;\n}\n\n/* The avatar's menu: who, then the pages, the theme, sign out, each with its glyph. */\n.menu-list.account {\n  min-width: 15rem;\n}\n\n.menu-list .menu-person {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 8px 10px 10px;\n  color: var(--tempra-color-text);\n}\n\n.menu-person .avatar-mark {\n  width: 32px;\n  height: 32px;\n  font-size: var(--tempra-text-label);\n}\n\n.menu-person-names {\n  display: flex;\n  flex-direction: column;\n  min-width: 0;\n  line-height: var(--tempra-leading-tight);\n}\n\n.menu-person-names .handle {\n  color: var(--tempra-color-faint);\n  font-size: var(--tempra-text-meta);\n}\n\n.menu-list a.menu-item,\n.menu-list button.menu-item {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n}\n\n.menu-item svg {\n  flex: none;\n  color: var(--tempra-color-muted);\n}\n\n/* The theme row: its name, then System, Light, Dark as one small segmented control. */\n.menu-list .menu-theme {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 6px 10px;\n  font-size: var(--tempra-text-ui);\n}\n\n.menu-theme svg {\n  flex: none;\n  color: var(--tempra-color-muted);\n}\n\n.menu-theme .segmented {\n  margin-left: auto;\n}\n\n.menu-theme .segmented button {\n  padding: 2px 8px;\n  font-size: var(--tempra-text-meta);\n}\n\n/* The library switcher's menu: libraries as rows with their tile and, when shared, the role. */\n.menu-list.libraries {\n  min-width: 17rem;\n}\n\n.menu-list a.menu-lib {\n  display: grid;\n  grid-template-columns: 20px minmax(0, 1fr) auto;\n  gap: 0 10px;\n  align-items: center;\n  padding: 6px 10px;\n}\n\n.menu-lib .lib-tile {\n  grid-row: span 2;\n  width: 20px;\n  height: 20px;\n  font-size: var(--tempra-text-label);\n}\n\n.menu-lib .menu-lib-role {\n  grid-column: 2;\n  color: var(--tempra-color-faint);\n  font-size: var(--tempra-text-meta);\n}\n\n.menu-lib .menu-lib-check {\n  grid-column: 3;\n  grid-row: span 2;\n  display: inline-flex;\n  color: var(--tempra-color-muted);\n}\n\n/* The sidebar: a hairline on its right; the views, a rule, the files (which scroll), and\n   Settings at its foot. A settings frame holds a way back and its tabs instead. */\n.ws-sidebar {\n  grid-area: sidebar;\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  min-width: 0;\n  min-height: 0;\n  padding: 12px 10px;\n  border-right: 1px solid var(--tempra-color-border);\n  background: var(--tempra-color-bg);\n  font-size: var(--tempra-text-ui);\n}\n\n.ws-sidebar[hidden] {\n  display: none;\n}\n\n.sidebar-rule {\n  margin: 10px 8px;\n}\n\n.sidebar-label {\n  margin: 14px 10px 4px;\n  color: var(--tempra-color-faint);\n  font-size: var(--tempra-text-meta);\n}\n\n.sidebar-scroll {\n  flex: 1;\n  min-height: 0;\n  overflow: auto;\n  padding-bottom: 16px;\n}\n\n.sidebar-foot {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  padding-top: 8px;\n}\n\n/* The way back at the top of a settings sidebar: \"‹ Back to tempra-dev\". */\n.nav-row.back {\n  margin-bottom: 14px;\n  color: var(--tempra-color-muted);\n}\n\n.nav-row.back:hover {\n  color: var(--tempra-color-text);\n}\n\n/* A library in the account's sidebar: its tile, its name, what is for the person there. */\n.nav-row .lib-tile {\n  width: 20px;\n  height: 20px;\n  font-size: var(--tempra-text-label);\n}\n\n.nav-row .lib-tile.shared {\n  border-radius: 50%;\n  background: var(--tempra-color-muted);\n}\n\n/* The page: the frame's scroller. Its width, not the window's, decides a concept's columns\n   (container queries on `sheet`, kept by that name from take 3, in concept.css), so hiding the\n   sidebar widens the reading layout. */\n.ws-main {\n  grid-area: main;\n  min-width: 0;\n  min-height: 0;\n  overflow: hidden auto;\n  background: var(--tempra-color-bg);\n  container: sheet / inline-size;\n}\n\n/* Showing the hidden sidebar: a quiet glyph at the left of the crumbs. */\n.sheet-toggle {\n  flex: none;\n  color: var(--tempra-color-faint);\n}\n\n/* The change dot's second state (take 4): pulsing while an agent writes. */\n.change-dot.live {\n  background: var(--tempra-color-agent);\n  animation: tempra-pulse var(--tempra-pulse) ease-in-out infinite;\n}\n\n@keyframes tempra-pulse {\n  0%,\n  100% {\n    opacity: 1;\n    transform: scale(1);\n  }\n\n  50% {\n    opacity: 0.45;\n    transform: scale(0.7);\n  }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .change-dot.live {\n    animation: none;\n  }\n}\n\n.lib-tile,\n.wordmark-tile {\n  display: grid;\n  flex: none;\n  place-items: center;\n  width: 24px;\n  height: 24px;\n  border-radius: var(--tempra-radius-tile);\n  background: var(--tempra-color-text);\n  color: var(--tempra-color-bg);\n  font-size: var(--tempra-text-name);\n  font-weight: var(--tempra-weight-strong);\n}\n\n.lib-names {\n  display: flex;\n  flex-direction: column;\n  min-width: 0;\n  line-height: var(--tempra-leading-tight);\n}\n\n.lib-name {\n  overflow: hidden;\n  font-weight: var(--tempra-weight-strong);\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.lib-owner {\n  overflow: hidden;\n  color: var(--tempra-color-faint);\n  font-size: var(--tempra-text-label);\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.nav {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n}\n\n/* A row in the sidebar: a glyph, a name, a count or mark at the end. */\n.nav-row {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  width: 100%;\n  min-height: var(--tempra-row);\n  padding: 4px 10px;\n  border: 0;\n  border-radius: var(--tempra-radius-row);\n  background: transparent;\n  color: var(--tempra-color-text);\n  font-size: var(--tempra-text-ui);\n  text-align: left;\n  text-decoration: none;\n}\n\n.nav-row:visited {\n  color: var(--tempra-color-text);\n}\n\n.nav-row:hover,\n.nav-row:hover:not(:disabled) {\n  background: var(--tempra-color-hover);\n  color: var(--tempra-color-text);\n}\n\n.nav-row[aria-current=\"page\"],\n.nav-row[aria-current=\"location\"] {\n  background: var(--tempra-color-selected);\n  font-weight: var(--tempra-weight-medium);\n}\n\n.nav-row svg {\n  flex: none;\n}\n\n.nav-label {\n  flex: 1;\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.nav-count {\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n  font-variant-numeric: tabular-nums;\n}\n\n.nav-row.person {\n  padding-left: 8px;\n}\n\n.nav-row.person .avatar-mark {\n  margin-right: 0;\n}\n\n/* The tree: nested lists, one row per folder or file, indented a step a level. A folder's row is\n   a button that opens and closes it (a chevron turns) with its count of concepts; a file's row is\n   a link. */\n.tree,\n.tree ul {\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.tree ul {\n  padding-left: 12px;\n}\n\n.tree li {\n  margin: 0;\n}\n\n.tree-row {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  min-height: var(--tempra-row);\n  margin-bottom: 1px;\n  padding: 0 10px 0 4px;\n  border-radius: var(--tempra-radius-row);\n  font-size: var(--tempra-text-ui);\n  white-space: nowrap;\n}\n\n.tree-row:hover {\n  background: var(--tempra-color-hover);\n}\n\nbutton.tree-row {\n  width: 100%;\n  border: 0;\n  background: none;\n  color: var(--tempra-color-text);\n  font: inherit;\n  font-size: var(--tempra-text-ui);\n  text-align: left;\n}\n\nbutton.tree-row:hover:not(:disabled) {\n  background: var(--tempra-color-hover);\n}\n\nbutton.tree-row[aria-current=\"page\"] {\n  background: var(--tempra-color-selected);\n}\n\n.tree-chevron {\n  flex: none;\n  display: flex;\n  width: 16px;\n  color: var(--tempra-color-faint);\n  transition: transform 0.15s ease;\n}\n\n.tree-chevron svg {\n  width: 12px;\n  height: 12px;\n}\n\n.tree-row[aria-expanded=\"true\"] .tree-chevron {\n  transform: rotate(90deg);\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .tree-chevron {\n    transition: none;\n  }\n}\n\n.tree-name {\n  flex: 1;\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.tree-count {\n  flex: none;\n  color: var(--tempra-color-faint);\n  font-size: var(--tempra-text-label);\n  font-variant-numeric: tabular-nums;\n}\n\n.tree-row > a {\n  flex: 1;\n  min-width: 0;\n  overflow: hidden;\n  color: var(--tempra-color-muted);\n  text-decoration: none;\n  text-overflow: ellipsis;\n}\n\n.tree-row:has(> [aria-current=\"page\"]) {\n  background: var(--tempra-color-selected);\n}\n\n.tree-row > a[aria-current=\"page\"] {\n  color: var(--tempra-color-text);\n  font-weight: var(--tempra-weight-medium);\n}\n\n.tree-leaf {\n  flex: none;\n  width: 16px;\n}\n\n/* Marks: an agent's change (a dot), open comments (a count), a clock (stale) or an hourglass\n   (stale soon). */\n.tree-mark {\n  display: inline-flex;\n  flex: none;\n  align-items: center;\n  color: var(--tempra-color-faint);\n  font-size: var(--tempra-text-label);\n  font-variant-numeric: tabular-nums;\n}\n\n.tree-note {\n  padding: 4px 10px;\n  color: var(--tempra-color-faint);\n  font-size: var(--tempra-text-meta);\n}\n\n/* ---------- The quick switcher ---------- */\n\n.switcher {\n  width: min(36rem, 90vw);\n  padding: 12px;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-card);\n  background: var(--tempra-color-bg);\n  box-shadow: var(--tempra-shadow);\n  color: var(--tempra-color-text);\n}\n\n.switcher::backdrop {\n  background: var(--tempra-color-scrim);\n}\n\n.switcher-head input {\n  width: 100%;\n  border-radius: var(--tempra-radius-pill);\n}\n\n.switcher [role=\"listbox\"] {\n  margin-top: var(--tempra-space-2);\n}\n\n.switcher [role=\"option\"] {\n  padding: 6px 10px;\n  border-radius: var(--tempra-radius-row);\n  cursor: pointer;\n}\n\n.switcher [role=\"option\"][aria-selected=\"true\"] {\n  background: var(--tempra-color-selected);\n}\n\n/* ---------- Narrow screens: a top bar, the sidebar as a drawer ---------- */\n\n/* The phone's pieces of the top bar (the menu button, where the person is) and of the drawer\n   (the Inbox row at its foot) show only here. */\n.ws-menu,\n.ws-topbar-place,\n.phone-only {\n  display: none;\n}\n\n@media (max-width: 900px) {\n  .workspace,\n  .workspace.sidebar-hidden {\n    grid-template-columns: minmax(0, 1fr);\n    grid-template-rows: var(--tempra-bar) minmax(0, 1fr);\n    grid-template-areas:\n      \"topbar\"\n      \"main\";\n  }\n\n  .ws-topbar,\n  .sidebar-hidden .ws-topbar {\n    display: flex;\n    align-items: center;\n    gap: 4px;\n    padding: 0 6px;\n  }\n\n  .topbar-brand,\n  .topbar-crumbs,\n  .sheet-toggle,\n  .topbar-end .bell {\n    display: none;\n  }\n\n  .topbar-page {\n    flex: 1;\n    gap: 4px;\n    padding: 0;\n  }\n\n  /* The way to everything else, in ink so it reads as the bar's first control. */\n  .ws-menu {\n    display: inline-flex;\n    color: var(--tempra-color-text);\n  }\n\n  .nav-row.phone-only {\n    display: flex;\n  }\n\n  /* Where the person is: the library's tile and name, the page beneath it. */\n  .ws-topbar-place {\n    display: flex;\n    flex: 1;\n    align-items: center;\n    gap: 10px;\n    min-width: 0;\n    min-height: var(--tempra-touch);\n    padding: 0 8px;\n    border-radius: var(--tempra-radius-row);\n    color: var(--tempra-color-text);\n    text-decoration: none;\n  }\n\n  .ws-topbar-place:visited {\n    color: var(--tempra-color-text);\n  }\n\n  .ws-topbar-place .lib-tile {\n    width: 24px;\n    height: 24px;\n  }\n\n  .ws-topbar-here {\n    overflow: hidden;\n    color: var(--tempra-color-muted);\n    font-size: var(--tempra-text-meta);\n    text-overflow: ellipsis;\n    white-space: nowrap;\n  }\n\n  .topbar-tools .icon-button.with-count,\n  .topbar-tools .icon-button:not(.with-count),\n  .topbar-end .icon-button {\n    height: var(--tempra-touch);\n    border: 0;\n  }\n\n  .topbar-tools .icon-button:not(.with-count),\n  .topbar-end .icon-button {\n    width: var(--tempra-touch);\n  }\n\n  .ws-sidebar {\n    position: fixed;\n    top: var(--tempra-bar);\n    bottom: 0;\n    left: 0;\n    z-index: 6;\n    display: none;\n    width: min(var(--tempra-sidebar), calc(100vw - 2 * var(--tempra-gutter)));\n    padding: 8px;\n    border-right: 1px solid var(--tempra-color-border);\n    background: var(--tempra-color-bg);\n    box-shadow: var(--tempra-shadow);\n  }\n\n  .ws-sidebar.open {\n    display: flex;\n  }\n\n  .ws-sidebar:focus {\n    outline: none;\n  }\n\n  /* In the drawer, the switcher and search sit at the top. */\n  .drawer-head {\n    display: flex;\n    align-items: center;\n    gap: 6px;\n    margin-bottom: 6px;\n  }\n\n  /* Touch targets: every row and control at least 44px tall. */\n  .nav-row,\n  .tree-row,\n  .lib-switch {\n    min-height: var(--tempra-touch);\n  }\n\n  .icon-button.touch {\n    width: var(--tempra-touch);\n    height: var(--tempra-touch);\n  }\n\n  .sheet-page,\n  .page {\n    padding: 32px 16px 72px;\n  }\n}\n\n/* Outside a phone the drawer's head is not drawn: the top bar holds the switcher and search. */\n@media (min-width: 901px) {\n  .drawer-head {\n    display: none;\n  }\n}\n\n/* ---------- Page pieces: lists, tables, forms, the ledger, diffs ---------- */\n\n.new-library {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 8px;\n  margin: -12px 0 24px;\n  padding: 12px 18px;\n  border-radius: var(--tempra-radius-box);\n  background: var(--tempra-color-bg);\n  box-shadow: var(--tempra-shadow);\n  font-size: var(--tempra-text-ui);\n}\n\n.new-library .notice {\n  flex-basis: 100%;\n  margin: 0;\n}\n\n/* A command or URL to copy (the connect pages): an inset that wraps rather than widening the page. */\n.page pre,\n.sheet-page pre {\n  margin: 0 0 var(--tempra-space-3);\n  padding: 10px 14px;\n  border-radius: var(--tempra-radius-row);\n  background: var(--tempra-color-ground);\n  font-size: var(--tempra-text-ui);\n  line-height: var(--tempra-line-height);\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n}\n\n.sheet-page pre,\n.sheet-page pre.src,\n.sheet-page pre.diff {\n  background: var(--tempra-color-ground);\n}\n\n/* Dates and short facts in a table keep to one line. */\ntable.list td.when,\ntable.list .nowrap {\n  white-space: nowrap;\n}\n\n.table-wrap {\n  overflow-x: auto;\n  margin: 0 0 var(--tempra-space-3);\n}\n\ntable.list {\n  width: 100%;\n  font-size: var(--tempra-text-ui);\n}\n\ntable.list th {\n  padding: 6px 10px;\n  border-bottom: 1px solid var(--tempra-color-border);\n  color: var(--tempra-color-faint);\n  font-size: var(--tempra-text-label);\n  font-weight: var(--tempra-weight-regular);\n  letter-spacing: 0.04em;\n  text-transform: uppercase;\n}\n\ntable.list td {\n  padding: 10px;\n  border-bottom: 1px solid var(--tempra-color-border);\n}\n\ntable.list td.name a {\n  font-weight: var(--tempra-weight-medium);\n}\n\n/* A setting on one line: its name, then its control (the Account page's theme). */\n.field-row {\n  display: flex;\n  align-items: center;\n  gap: 16px;\n}\n\n/* A group of related controls on a page (a form, a list with its actions). */\n.panel-box {\n  margin: 0 0 var(--tempra-space-4);\n  padding: 16px 18px;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-box);\n  background: var(--tempra-color-bg);\n}\n\n.panel-box > h2:first-child {\n  margin-top: 0;\n}\n\nform.inline,\nform.filters,\nform.token {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 8px;\n}\n\n/* The ledger's filters: small labels, inset fields, no box. */\nform.filters {\n  margin: 0 0 var(--tempra-space-3);\n  color: var(--tempra-color-faint);\n  font-size: var(--tempra-text-meta);\n}\n\nform.filters label {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n}\n\nform.filters input {\n  padding: 4px 10px;\n  border: 0;\n  border-radius: var(--tempra-radius-pill);\n  background: var(--tempra-color-ground);\n  color: var(--tempra-color-text);\n}\n\nform.filters input[type=\"text\"] {\n  width: 9rem;\n}\n\nform.filters button {\n  padding: 4px 12px;\n  font-size: var(--tempra-text-meta);\n}\n\nform.token {\n  align-items: flex-start;\n  flex-direction: column;\n}\n\npre.src,\npre.diff {\n  overflow-x: auto;\n  padding: 12px 14px;\n  border-radius: var(--tempra-radius-box);\n  background: var(--tempra-color-ground);\n  font-size: var(--tempra-text-meta);\n  line-height: var(--tempra-line-height);\n}\n\npre.src.wrap {\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n}\n\npre.diff .add {\n  font-weight: var(--tempra-weight-strong);\n}\n\npre.diff .del {\n  color: var(--tempra-color-faint);\n  text-decoration: line-through;\n}\n\npre.diff .hunk,\npre.diff .meta {\n  color: var(--tempra-color-muted);\n}\n\nol.ledger {\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.request {\n  padding: 12px 0;\n  border-top: 1px solid var(--tempra-color-border);\n  font-size: var(--tempra-text-ui);\n}\n\n.req-head {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: baseline;\n  gap: 4px 8px;\n}\n\n.request .note {\n  margin: 4px 0;\n  color: var(--tempra-color-muted);\n}\n\nul.events {\n  margin: 4px 0 0;\n  padding: 0;\n  list-style: none;\n  font-size: var(--tempra-text-meta);\n}\n\n.op {\n  display: inline-block;\n  min-width: 3.5em;\n  color: var(--tempra-color-muted);\n  font-family: var(--tempra-font-mono);\n  font-size: var(--tempra-text-label);\n}\n\n/* ---------- Notifications (TEMPRA-72, TEMPRA-73): the inbox, mentions ---------- */\n\n.inbox-list {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.inbox-list li {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: baseline;\n  gap: 4px 12px;\n  padding: 12px 18px;\n  border-radius: var(--tempra-radius-box);\n}\n\n.inbox-list li:hover {\n  background: var(--tempra-color-hover);\n}\n\n.inbox-list .what {\n  flex: 1 1 20rem;\n}\n\n.inbox-list .unread .what a {\n  font-weight: var(--tempra-weight-strong);\n}\n\n.inbox-list .when {\n  font-size: var(--tempra-text-meta);\n}\n\n.inbox-list .excerpt {\n  flex-basis: 100%;\n  margin: 0;\n  color: var(--tempra-color-muted);\n}\n\n/* The comment box with its @ suggestions under it. */\n.mention-box {\n  position: relative;\n}\n\n.mention-list [aria-selected=\"true\"] {\n  background: var(--tempra-color-hover);\n}\n\n/*\n * A concept's page (take 3, TEMPRA-106; tempra-dev: app/reader): the sheet's bar, a slim review\n * bar while the text shows changes, then three columns: the contents in the left margin, the text\n * (title, description, byline, body, sources), the comments in the right margin. The sheet's width\n * decides what fits (container queries on `sheet`, the sheet's scroller), and it tells the app how\n * comments are shown through `--comments-mode`: in the margin, a sheet over the right side, or a\n * sheet from the bottom.\n */\n\n.concept {\n  --comments-mode: margin;\n}\n\n.concept-grid {\n  display: grid;\n  grid-template-columns:\n    [contents] minmax(0, 1fr)\n    [text] minmax(0, var(--tempra-column-text))\n    [rest] minmax(0, 1fr);\n  column-gap: var(--tempra-margin-gap);\n  padding: 0 var(--tempra-sheet-pad) 140px;\n}\n\n/* Comments on: the text moves left to make room for the margin beside it. */\n.concept.comments-on .concept-grid {\n  grid-template-columns:\n    [contents] minmax(0, 1fr)\n    [text] minmax(0, var(--tempra-column-text))\n    [comments] var(--tempra-margin-comments)\n    [rest] minmax(0, 0.5fr);\n}\n\n.concept .doc {\n  grid-row: 1;\n  grid-column: text;\n  min-width: 0;\n  padding-top: 40px;\n}\n\n/* The contents: a short list of headings in small grey type beside the text, kept in view. */\n.concept-contents {\n  position: sticky;\n  top: 48px;\n  grid-row: 1;\n  grid-column: contents;\n  justify-self: end;\n  align-self: start;\n  width: min(100%, var(--tempra-margin-contents));\n  margin-top: 220px;\n}\n\n.toc {\n  margin: 0;\n  padding: 0;\n  list-style: none;\n  font-size: var(--tempra-text-meta);\n  line-height: var(--tempra-line-height);\n}\n\n.toc a {\n  display: block;\n  padding: 4px 0;\n  color: var(--tempra-color-faint);\n  text-decoration: none;\n}\n\n.toc .sub a {\n  padding-left: 12px;\n}\n\n.toc a:hover,\n.toc a[aria-current=\"location\"] {\n  color: var(--tempra-color-text);\n}\n\n/* The Contents item in \"…\" is for when the margin cannot show them. */\n.concept.has-contents .more-contents {\n  display: none;\n}\n\n/* Where a crumb notes what is exceptional (stale, a status that is not stable). */\n.crumb-flag {\n  color: var(--tempra-color-muted);\n}\n\n.crumb-flag::before {\n  content: \"·\";\n  margin-right: 6px;\n}\n\n.doc-head {\n  margin-bottom: 32px;\n}\n\n.doc-title {\n  margin: 0 0 12px;\n  font-family: var(--tempra-font-reader);\n  font-size: var(--tempra-text-title);\n  font-weight: var(--tempra-weight-medium);\n  line-height: var(--tempra-leading-tight);\n  letter-spacing: -0.01em;\n}\n\n.doc-tagline {\n  margin: 0;\n  color: var(--tempra-color-muted);\n  font-family: var(--tempra-font-reader);\n  font-size: var(--tempra-text-reader);\n  line-height: var(--tempra-line-height);\n}\n\n/* ---------- The byline: who wrote this version, and its versions ---------- */\n\n.byline {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  justify-content: space-between;\n  gap: 10px 16px;\n  margin-top: 24px;\n  padding-bottom: 20px;\n  border-bottom: 1px solid var(--tempra-color-border);\n  font-size: var(--tempra-text-ui);\n}\n\n.byline-who {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 8px;\n  min-width: 0;\n}\n\n.byline-name strong {\n  font-weight: var(--tempra-weight-medium);\n}\n\n.byline-sep {\n  color: var(--tempra-color-faint);\n}\n\n/* \"6 versions\": a quiet grey pill that opens the history menu. */\n.byline-versions {\n  padding: 2px 8px;\n  border: 0;\n  border-radius: var(--tempra-radius-mark);\n  background: var(--tempra-color-ground);\n  color: var(--tempra-color-text);\n  font-size: var(--tempra-text-ui);\n}\n\n.byline-versions:hover:not(:disabled),\n.byline-versions[aria-expanded=\"true\"] {\n  background: var(--tempra-color-selected);\n}\n\n/* The history menu under the byline: the latest versions, then all of them. */\n.byline .menu-list {\n  min-width: 22rem;\n  max-width: min(26rem, calc(100vw - 32px));\n}\n\n.menu-list a.history-row {\n  display: grid;\n  grid-template-columns: 20px minmax(0, 1fr) auto;\n  gap: 10px;\n  align-items: start;\n}\n\n.menu-list a.history-row.current {\n  background: var(--tempra-color-ground);\n}\n\n.history-n {\n  color: var(--tempra-color-faint);\n  font-variant-numeric: tabular-nums;\n}\n\n.history-what {\n  display: flex;\n  flex-direction: column;\n  min-width: 0;\n}\n\n.history-who {\n  font-weight: var(--tempra-weight-medium);\n}\n\n.history-note {\n  overflow: hidden;\n  color: var(--tempra-color-muted);\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.history-when {\n  color: var(--tempra-color-faint);\n  font-size: var(--tempra-text-meta);\n  white-space: nowrap;\n}\n\n.menu-list .history-all {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n}\n\n/* All versions, in a dialog: one row per event. */\n.history {\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.history li {\n  display: flex;\n  justify-content: space-between;\n  gap: 12px;\n  padding: 8px 4px;\n  border-top: 1px solid var(--tempra-color-border);\n  font-size: var(--tempra-text-ui);\n}\n\n.history li.current {\n  background: var(--tempra-color-ground);\n}\n\n.history li.verify .history-what > a,\n.history li.verify .history-what {\n  font-weight: var(--tempra-weight-medium);\n}\n\n.history .history-what {\n  flex-direction: row;\n  flex-wrap: wrap;\n  gap: 0 8px;\n}\n\n.history .history-note {\n  flex-basis: 100%;\n  white-space: normal;\n}\n\n.history .history-when a {\n  color: inherit;\n}\n\n/* ---------- Review mode, and the changes since a chosen version ---------- */\n\n.review-bar {\n  position: sticky;\n  top: var(--tempra-bar);\n  z-index: 2;\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 8px 16px;\n  margin: 0 14px;\n  padding: 8px 14px;\n  border-radius: var(--tempra-radius-box);\n  background: var(--tempra-color-ground);\n  font-size: var(--tempra-text-ui);\n}\n\n.review-what {\n  flex: 1 1 16rem;\n  min-width: 0;\n}\n\n.review-actions {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 8px 12px;\n}\n\n.verify-form {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 6px;\n}\n\n.verify-form input {\n  flex: 1 1 10rem;\n  min-width: 0;\n}\n\n/* ---------- The end of the body: sources, the Markdown view ---------- */\n\n.doc-sources {\n  max-width: var(--tempra-measure-reader);\n  margin-top: 56px;\n  padding-top: 20px;\n  border-top: 1px solid var(--tempra-color-border);\n}\n\n.doc-sources h2 {\n  margin: 0 0 12px;\n  font-size: var(--tempra-text-ui);\n  font-weight: var(--tempra-weight-strong);\n}\n\n.doc-sources h3 {\n  margin: 20px 0 8px;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n  font-weight: var(--tempra-weight-medium);\n}\n\n.sources {\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.sources li {\n  display: grid;\n  grid-template-columns: 20px minmax(0, 1fr);\n  gap: 6px;\n  margin-bottom: 10px;\n  font-size: var(--tempra-text-ui);\n  line-height: var(--tempra-line-height);\n}\n\n.sources li:target {\n  background: var(--tempra-color-ground);\n}\n\n.sources .num {\n  color: var(--tempra-color-faint);\n  font-variant-numeric: tabular-nums;\n}\n\n.sources .meta {\n  display: block;\n  color: var(--tempra-color-faint);\n  font-size: var(--tempra-text-meta);\n}\n\n.sources a {\n  color: var(--tempra-color-text);\n}\n\n.raw-markdown pre {\n  margin: 0 0 var(--tempra-space-2);\n  padding: 16px 18px;\n  border-radius: var(--tempra-radius-box);\n  background: var(--tempra-color-ground);\n  font-size: var(--tempra-text-ui);\n  line-height: var(--tempra-line-height);\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n}\n\n/* ---------- Properties and agent notes (dialogs from \"…\") ---------- */\n\n.facts {\n  display: grid;\n  grid-template-columns: 7rem minmax(0, 1fr);\n  gap: 6px 12px;\n  margin: 0 0 var(--tempra-space-3);\n  font-size: var(--tempra-text-meta);\n}\n\n.facts > div {\n  display: contents;\n}\n\n.facts dt {\n  color: var(--tempra-color-faint);\n  font-family: var(--tempra-font-mono);\n  font-size: var(--tempra-text-label);\n  line-height: var(--tempra-line-height);\n}\n\n.facts dd {\n  min-width: 0;\n  margin: 0;\n  overflow-wrap: anywhere;\n}\n\n.facts pre {\n  margin: 0;\n  white-space: pre-wrap;\n}\n\n.linked li,\n.notes-list li {\n  margin-bottom: 8px;\n  font-size: var(--tempra-text-meta);\n}\n\n.notes-list {\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n/* ---------- What fits: the sheet's width decides ---------- */\n\n/* No room for the contents beside the text and the comments: they move into \"…\". */\n@container sheet (width < 1280px) {\n  .concept.comments-on .concept-contents {\n    display: none;\n  }\n\n  .concept.comments-on .more-contents {\n    display: block;\n  }\n}\n\n@container sheet (width < 1100px) {\n  .concept-contents {\n    display: none;\n  }\n\n  .concept.has-contents .more-contents {\n    display: block;\n  }\n}\n\n/* No room for a margin: the comments open as a sheet over the right side of the page, and the\n   text keeps its column. */\n@container sheet (width < 980px) {\n  .concept {\n    --comments-mode: side;\n  }\n\n  .concept.comments-on .concept-grid {\n    grid-template-columns:\n      [contents] minmax(0, 1fr)\n      [text] minmax(0, var(--tempra-column-text))\n      [rest] minmax(0, 1fr);\n  }\n}\n\n/* A phone: one column with a 16px gutter, and comments in a sheet from the bottom. */\n@container sheet (width < 640px) {\n  .concept {\n    --comments-mode: bottom;\n  }\n\n  .concept-grid,\n  .concept.comments-on .concept-grid {\n    grid-template-columns: [text] minmax(0, 1fr);\n    padding: 0 16px 96px;\n  }\n\n  .concept .doc {\n    padding-top: 16px;\n  }\n\n  .doc-title {\n    font-size: var(--tempra-text-page);\n  }\n\n  .review-bar {\n    margin: 0 6px;\n  }\n}\n\n/*\n * Comments on a concept (take 3, TEMPRA-106; tempra-dev: app/comments). In the margin, each\n * thread sits beside the line its quote is on (the app sets `--slot-y` on each slot, measured and\n * pushed down past the one before); the active one is a card joined to its quote by a hairline,\n * the others one line each. Where there is no margin, the same list is a sheet over the right side\n * of the page, or on a phone a sheet from the bottom. Lines and greys only: no colour.\n */\n\n.concept-comments {\n  grid-row: 1;\n  grid-column: comments;\n  min-width: 0;\n  padding-top: 40px;\n  font-size: var(--tempra-text-ui);\n}\n\n.comments-head {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n\n.comments-head h2 {\n  margin: 0;\n  font-size: var(--tempra-text-ui);\n  font-weight: var(--tempra-weight-strong);\n}\n\n.comments-head .count {\n  flex: 1;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n}\n\n.comments-body {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\n.new-thread,\n.show-resolved {\n  align-self: flex-start;\n  padding-left: 8px;\n  font-size: var(--tempra-text-meta);\n}\n\n/* In the margin, slots are placed by the app; in a sheet they stack. */\n.comments-slots {\n  position: relative;\n  min-height: var(--margin-height, 0);\n}\n\n.concept-comments.margin .slot {\n  position: absolute;\n  top: var(--slot-y, 0);\n  right: 0;\n  left: 0;\n}\n\n.concept-comments:not(.margin) .comments-slots {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\n/* The hairline from the active thread's quote to the thread, across the gap. */\n.thread-line {\n  position: absolute;\n  top: calc(var(--line-y, 0) + 0.8em);\n  left: calc(-1 * var(--tempra-margin-gap));\n  width: calc(var(--tempra-margin-gap) - 8px);\n  border-top: 1px solid var(--tempra-color-border-strong);\n}\n\n.concept-comments:not(.margin) .thread-line {\n  display: none;\n}\n\n/* A thread's quote is beside it in the margin; in a sheet it is shown with the thread. */\n.concept-comments.margin .thread-quote {\n  display: none;\n}\n\n/* A collapsed thread: one line, who, the first words, when. */\n.thread.collapsed {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  width: 100%;\n  min-height: var(--tempra-row);\n  padding: 4px 8px;\n  border: 0;\n  border-radius: var(--tempra-radius-row);\n  background: transparent;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n  text-align: left;\n}\n\n.thread.collapsed:hover:not(:disabled) {\n  background: var(--tempra-color-hover);\n}\n\n.thread.collapsed .avatar-mark {\n  width: var(--tempra-avatar-small);\n  height: var(--tempra-avatar-small);\n  font-size: var(--tempra-text-initial);\n}\n\n.thread.collapsed strong {\n  flex: none;\n  color: var(--tempra-color-text);\n  font-weight: var(--tempra-weight-medium);\n}\n\n.thread-words {\n  flex: 1;\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.thread-replies {\n  flex: none;\n  color: var(--tempra-color-faint);\n  font-variant-numeric: tabular-nums;\n}\n\n.thread.collapsed time {\n  flex: none;\n  color: var(--tempra-color-faint);\n}\n\n.thread.resolved {\n  opacity: 0.7;\n}\n\n/* The active thread (and a new comment): a card with the comments, a reply, Resolve. */\n.thread.open {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  padding: 12px;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-box);\n  background: var(--tempra-color-bg);\n}\n\n.said-by {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  font-size: var(--tempra-text-meta);\n}\n\n.said-by strong {\n  font-weight: var(--tempra-weight-medium);\n}\n\n.said-by time,\n.said-change {\n  color: var(--tempra-color-faint);\n  font-size: var(--tempra-text-meta);\n}\n\n.said-change {\n  margin: 0;\n}\n\n.comment {\n  margin: 4px 0 0 calc(var(--tempra-avatar) + 8px);\n  font-size: var(--tempra-text-ui);\n  line-height: var(--tempra-line-height);\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n}\n\n.quote {\n  margin: 0;\n  padding-left: 10px;\n  border-left: 2px solid var(--tempra-color-border-strong);\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n  font-style: italic;\n  line-height: var(--tempra-line-height);\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n}\n\n.quote a {\n  color: inherit;\n  text-decoration: none;\n}\n\n/* The reply field, a pill until it has words; the composer's field, a box. */\n.reply-form,\n.comment-form {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\n.reply-form textarea,\n.comment-form textarea {\n  display: block;\n  width: 100%;\n  border: 0;\n  background: var(--tempra-color-ground);\n  font-size: var(--tempra-text-meta);\n}\n\n.reply-form textarea {\n  height: 2rem;\n  min-height: 0;\n  padding: 5px 12px;\n  border-radius: var(--tempra-radius-pill);\n  resize: none;\n}\n\n.reply-form textarea:focus,\n.reply-form textarea:not(:placeholder-shown) {\n  height: 4rem;\n  border-radius: var(--tempra-radius-box);\n}\n\n.comment-form textarea {\n  min-height: 4rem;\n  padding: 8px 10px;\n  border-radius: var(--tempra-radius-row);\n  resize: vertical;\n}\n\n.reply-form .actions,\n.comment-form .actions {\n  display: flex;\n  justify-content: flex-end;\n  gap: 6px;\n  margin: 0;\n}\n\n.reply-form button,\n.comment-form button {\n  padding: 4px 12px;\n  font-size: var(--tempra-text-meta);\n}\n\n/* No margin: a sheet over the right side of the page, under the sheet's bar. */\n.concept-comments.side,\n.concept-comments.bottom {\n  position: fixed;\n  z-index: 5;\n  overflow: auto;\n  padding: 12px 14px 20px;\n  border: 1px solid var(--tempra-color-border);\n  background: var(--tempra-color-bg);\n  box-shadow: var(--tempra-shadow);\n}\n\n.concept-comments.side {\n  top: calc(var(--tempra-topbar) + var(--tempra-gutter));\n  right: var(--tempra-gutter);\n  bottom: var(--tempra-gutter);\n  width: min(340px, calc(100vw - 4 * var(--tempra-gutter)));\n  border-radius: var(--tempra-radius-card);\n}\n\n/* A phone: a sheet from the bottom of the screen. */\n.concept-comments.bottom {\n  right: 0;\n  bottom: 0;\n  left: 0;\n  max-height: 75dvh;\n  border-bottom: 0;\n  border-radius: var(--tempra-radius-card) var(--tempra-radius-card) 0 0;\n}\n\n.concept-comments.bottom .comments-head {\n  position: sticky;\n  top: -12px;\n  margin: -12px -14px 4px;\n  padding: 4px 6px 4px 14px;\n  background: var(--tempra-color-bg);\n}\n\n.concept-comments.bottom .thread.collapsed {\n  min-height: var(--tempra-touch);\n}\n\n/*\n * The person's views of a library (take 3, TEMPRA-106; tempra-dev: app/home, app/needs-you,\n * app/activity, app/workspace): the library's home, Needs you, Activity and a folder. Quiet pages\n * in one column: a header, then sections of rows with hairlines between them.\n */\n\n/* ---------- Shared: a page's header and its sections ---------- */\n\n/* The header: the title (a concept title's look) and a quiet line, a link at the right. */\n.view-head {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: flex-end;\n  gap: var(--tempra-space-2) var(--tempra-space-3);\n  margin-bottom: var(--tempra-space-4);\n}\n\n.view-head-main {\n  display: flex;\n  flex: 1;\n  flex-direction: column;\n  gap: var(--tempra-space-1);\n  min-width: 0;\n}\n\n/* A view is the app, not a document: its title is the app's sans, sized as an h1 (TEMPRA-108). */\n.view-title {\n  margin: 0;\n  font-size: var(--tempra-text-page);\n  font-weight: var(--tempra-weight-strong);\n  line-height: var(--tempra-leading-tight);\n  letter-spacing: -0.02em;\n  overflow-wrap: anywhere;\n}\n\n.view-meta {\n  margin: 0;\n  color: var(--tempra-color-faint);\n  font-size: var(--tempra-text-meta);\n}\n\n/* A library's description under its name on the home (TEMPRA-102, take 4). */\n.view-lede {\n  margin: var(--tempra-space-1) 0 0;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-reader);\n  line-height: var(--tempra-line-height);\n}\n\n/* \"Live\": a small ink dot before the line. */\n.view-live {\n  display: flex;\n  align-items: center;\n  gap: var(--tempra-space-2);\n}\n\n.view-live::before {\n  content: \"\";\n  flex: none;\n  width: var(--tempra-dot);\n  height: var(--tempra-dot);\n  border-radius: 50%;\n  background: var(--tempra-color-text);\n}\n\n/* A link beside a header or a section's heading: \"The full ledger\", \"All 5\", \"Activity\". */\n.view-aside {\n  margin-left: auto;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n  white-space: nowrap;\n}\n\n.view-section-head {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: baseline;\n  gap: var(--tempra-space-1) var(--tempra-space-2);\n  margin-bottom: var(--tempra-space-2);\n}\n\n.view-section-title {\n  margin: 0;\n  font-size: var(--tempra-text-ui);\n  font-weight: var(--tempra-weight-strong);\n}\n\n.view-empty {\n  margin: 0;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-ui);\n}\n\n.view-more {\n  margin: var(--tempra-space-3) 0 0;\n}\n\n/* Filters: pills in a row that wraps. */\n.view-filters {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: var(--tempra-space-2);\n  margin-bottom: var(--tempra-space-4);\n  font-size: var(--tempra-text-meta);\n}\n\n.view-filters button,\n.view-filters select {\n  font-size: var(--tempra-text-meta);\n}\n\n/* A segmented control: buttons in one grey pill, the chosen one white. */\n.segmented {\n  display: flex;\n  gap: 2px;\n  min-width: 0;\n  margin: 0;\n  padding: 2px;\n  border: 0;\n  border-radius: var(--tempra-radius-pill);\n  background: var(--tempra-color-ground);\n}\n\n.segmented button {\n  border-color: transparent;\n  background: transparent;\n  color: var(--tempra-color-muted);\n}\n\n.segmented button[aria-pressed=\"true\"],\n.segmented button[aria-pressed=\"true\"]:hover:not(:disabled) {\n  border-color: var(--tempra-color-border);\n  background: var(--tempra-color-bg);\n  color: var(--tempra-color-text);\n}\n\n/* A choice as an outlined pill (a native select, so it works by keyboard and on a phone). */\n.pill-select {\n  border-color: var(--tempra-color-border);\n  border-radius: var(--tempra-radius-pill);\n  color: var(--tempra-color-muted);\n  cursor: pointer;\n}\n\n/* An outlined pill that stays pressed: ink edge and a grey fill when on. */\n.pill-toggle {\n  color: var(--tempra-color-muted);\n}\n\n.pill-toggle[aria-pressed=\"true\"],\n.pill-toggle[aria-pressed=\"true\"]:hover:not(:disabled) {\n  border-color: var(--tempra-color-text);\n  background: var(--tempra-color-selected);\n  color: var(--tempra-color-text);\n}\n\n@media (max-width: 900px) {\n  .view-title {\n    font-size: var(--tempra-text-h2);\n  }\n\n  .view-filters button,\n  .view-filters select {\n    min-height: var(--tempra-touch);\n  }\n\n  .segmented button {\n    min-height: calc(var(--tempra-touch) - 4px);\n  }\n}\n\n/* ---------- Home ---------- */\n\n.home-section {\n  margin-top: var(--tempra-space-4);\n}\n\n/* Who works here: their marks overlapping, each ringed in the sheet's white. */\n.home-who {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: var(--tempra-space-2);\n  margin-top: var(--tempra-space-1);\n}\n\n.face-stack {\n  display: flex;\n}\n\n.face-stack .avatar-mark {\n  box-sizing: content-box;\n  width: var(--tempra-avatar-small);\n  height: var(--tempra-avatar-small);\n  border: 2px solid var(--tempra-color-bg);\n  font-size: var(--tempra-text-initial);\n}\n\n.face-stack .avatar-mark + .avatar-mark {\n  margin-left: -6px;\n}\n\n/* Needs you: rows between hairlines, each one link. */\n.need-rows {\n  margin: 0;\n  padding: 0;\n  border-top: 1px solid var(--tempra-color-border);\n  list-style: none;\n}\n\n.need-rows > li {\n  border-bottom: 1px solid var(--tempra-color-border);\n}\n\n.need-row {\n  display: grid;\n  grid-template-columns: var(--tempra-avatar) minmax(0, 1fr) auto;\n  align-items: start;\n  gap: 12px;\n  min-height: var(--tempra-touch);\n  padding: 12px 4px;\n  color: var(--tempra-color-text);\n  text-decoration: none;\n}\n\n.need-row:hover {\n  background: var(--tempra-color-hover);\n}\n\n.need-row svg {\n  margin-top: 3px;\n}\n\n.need-text {\n  display: flex;\n  flex-direction: column;\n  min-width: 0;\n}\n\n.need-detail {\n  overflow: hidden;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-ui);\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.need-when {\n  color: var(--tempra-color-faint);\n  font-size: var(--tempra-text-meta);\n  white-space: nowrap;\n}\n\n/* The library's ways in, when the sidebar is not beside the sheet (TEMPRA-107): the sidebar's own\n   rows, their hover fill hanging into the gutter so their text lines up with the page's. */\n.home-ways {\n  margin: var(--tempra-space-3) -10px 0;\n}\n\n.home-ways-label {\n  margin: var(--tempra-space-3) 10px var(--tempra-space-1);\n  color: var(--tempra-color-faint);\n  font-size: var(--tempra-text-label);\n  font-weight: var(--tempra-weight-regular);\n}\n\n.home-ways .view-empty {\n  padding: 0 10px;\n}\n\n.home-files {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.home-entries {\n  display: flex;\n  flex-direction: column;\n  gap: var(--tempra-space-1);\n}\n\n/* A phone: no glyphs beside the needs, as on the board; the time stays at the right. */\n@media (max-width: 900px) {\n  .need-row {\n    grid-template-columns: minmax(0, 1fr) auto;\n    padding: 12px 0;\n  }\n\n  .need-row svg {\n    display: none;\n  }\n}\n\n/* ---------- Needs you ---------- */\n\n/* One column: the header, then a section per kind of need. */\n.needs {\n  display: flex;\n  flex-direction: column;\n  gap: 26px;\n}\n\n.needs-empty {\n  margin: 0;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-ui);\n}\n\n.needs-section {\n  display: flex;\n  flex-direction: column;\n  gap: var(--tempra-space-2);\n}\n\n.needs-section-head {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: baseline;\n  gap: 2px 10px;\n}\n\n.needs-section-head h2 {\n  margin: 0;\n  font-size: var(--tempra-text-ui);\n}\n\n.needs-count {\n  color: var(--tempra-color-faint);\n  font-weight: var(--tempra-weight-regular);\n}\n\n.needs-note {\n  color: var(--tempra-color-faint);\n  font-size: var(--tempra-text-meta);\n}\n\n/* A section's rows: one box, hairlines between them. */\n.needs-box {\n  margin: 0;\n  padding: 0;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-box);\n  list-style: none;\n  overflow: hidden;\n}\n\n.needs-box > li + li {\n  border-top: 1px solid var(--tempra-color-border);\n}\n\n.needs-row {\n  display: grid;\n  align-items: center;\n  gap: 16px;\n  padding: 11px 14px;\n}\n\n/* A thread waiting on a reply: the whole row is the link to it. */\n.needs-reply {\n  grid-template-columns: auto minmax(0, 1fr) auto;\n  align-items: start;\n  gap: 12px;\n  color: var(--tempra-color-text);\n  text-decoration: none;\n}\n\n.needs-reply:hover {\n  background: var(--tempra-color-hover);\n}\n\n.needs-reply b {\n  font-weight: var(--tempra-weight-medium);\n}\n\n.needs-verify {\n  grid-template-columns: minmax(0, 1fr) minmax(0, 160px) auto;\n}\n\n.needs-stale {\n  grid-template-columns: minmax(0, 1fr) auto;\n}\n\n.needs-main {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  min-width: 0;\n}\n\n.needs-title {\n  color: var(--tempra-color-text);\n  font-weight: var(--tempra-weight-medium);\n  text-decoration: none;\n}\n\n.needs-title:hover {\n  text-decoration: underline;\n}\n\n.needs-meta {\n  overflow: hidden;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.needs-for,\n.needs-by,\n.needs-asked {\n  color: var(--tempra-color-muted);\n}\n\n.needs-by,\n.needs-when,\n.needs-asked {\n  font-size: var(--tempra-text-meta);\n  white-space: nowrap;\n}\n\n.needs-when {\n  color: var(--tempra-color-faint);\n}\n\n.needs-by {\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n/* Review (a link) and Ask an agent (a button): the same outlined pill. */\n.needs-more {\n  align-self: flex-start;\n}\n\n.needs-error {\n  margin: 0;\n  font-size: var(--tempra-text-meta);\n  font-weight: var(--tempra-weight-medium);\n}\n\n/* What is counted, not listed (never verified, the agents' share): one quiet, collapsed line. */\n.needs-counted {\n  padding: 12px 14px;\n  border-radius: var(--tempra-radius-box);\n  background: var(--tempra-color-ground);\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-ui);\n}\n\n.needs-counted p {\n  margin: var(--tempra-space-2) 0 0;\n}\n\n/* A phone: who and the action go under the title; pills are touch targets. */\n@media (max-width: 900px) {\n  .needs-verify,\n  .needs-stale {\n    grid-template-columns: minmax(0, 1fr) auto;\n    gap: 6px 12px;\n  }\n\n  .needs-verify .needs-main,\n  .needs-stale .needs-main {\n    grid-column: 1 / -1;\n  }\n\n  .needs-stale .button,\n  .needs-stale button,\n  .needs-stale .needs-asked {\n    grid-column: 2;\n  }\n\n  .needs-reply {\n    grid-template-columns: auto minmax(0, 1fr);\n  }\n\n  .needs-reply .needs-when {\n    grid-column: 2;\n  }\n\n  .needs-row .button,\n  .needs-row button,\n  .needs-more {\n    min-height: var(--tempra-touch);\n  }\n}\n\n/* ---------- Activity ---------- */\n\n.activity-day {\n  display: flex;\n  flex-direction: column;\n  gap: var(--tempra-space-1);\n  margin-bottom: var(--tempra-space-4);\n}\n\n/* An entry: who, what they did, when; new ones on a faint fill with a dot at the right. */\n.entry {\n  display: grid;\n  grid-template-columns: var(--tempra-avatar) minmax(0, 1fr) auto;\n  gap: 12px;\n  padding: 12px 10px;\n  border-radius: var(--tempra-radius-box);\n  font-size: var(--tempra-text-ui);\n}\n\n.entry.new {\n  background: var(--tempra-color-ground);\n}\n\n.entry > .avatar-mark {\n  margin-top: 1px;\n}\n\n.entry-body {\n  display: flex;\n  flex-direction: column;\n  gap: var(--tempra-space-1);\n  min-width: 0;\n}\n\n.entry-line {\n  margin: 0;\n  font-size: var(--tempra-font-size);\n  overflow-wrap: anywhere;\n}\n\n.entry-who {\n  font-weight: var(--tempra-weight-medium);\n}\n\n.entry-for,\n.entry-words,\n.entry-more {\n  color: var(--tempra-color-faint);\n}\n\n.entry-words {\n  font-size: var(--tempra-text-meta);\n}\n\n/* The request's note, quoted. */\n.entry-note {\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-font-size);\n  overflow-wrap: anywhere;\n}\n\n.entry-titles {\n  margin: 0;\n  overflow: hidden;\n  color: var(--tempra-color-muted);\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n/* The concepts it touched: what happened, the title, the words changed. */\n.entry-touched {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  margin: var(--tempra-space-1) 0 0;\n  padding: 0;\n  list-style: none;\n}\n\n.entry-touched li {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: baseline;\n  gap: 0 10px;\n  min-width: 0;\n}\n\n.entry-what {\n  flex: none;\n  width: 52px;\n  color: var(--tempra-color-faint);\n  font-size: var(--tempra-text-label);\n}\n\n.entry-side {\n  display: flex;\n  flex-direction: column;\n  align-items: flex-end;\n  gap: var(--tempra-space-2);\n  color: var(--tempra-color-faint);\n  font-size: var(--tempra-text-meta);\n  white-space: nowrap;\n}\n\n/* On the home: smaller marks, no fill, the note in the body's face. */\n.entry.compact {\n  padding: 6px 0;\n  background: none;\n}\n\n.entry.compact > .avatar-mark {\n  width: var(--tempra-avatar-small);\n  height: var(--tempra-avatar-small);\n  font-size: var(--tempra-text-initial);\n}\n\n.entry.compact .entry-line {\n  font-size: var(--tempra-text-ui);\n}\n\n.entry.compact .entry-note {\n  font-family: inherit;\n  font-size: var(--tempra-text-ui);\n}\n\n@media (max-width: 900px) {\n  .entry {\n    gap: 10px;\n    padding: 12px 8px;\n  }\n\n  .entry.compact .entry-note,\n  .entry.compact .entry-titles {\n    display: none;\n  }\n}\n\n/* ---------- A folder ---------- */\n\n.folder {\n  display: flex;\n  flex-direction: column;\n  gap: 22px;\n}\n\n.folder-legend,\n.folder-empty {\n  margin: 0;\n  color: var(--tempra-color-faint);\n  font-size: var(--tempra-text-meta);\n}\n\n/* Rows between hairlines: subfolders first, then concepts. */\n.folder-list {\n  margin: 0;\n  padding: 0;\n  border-top: 1px solid var(--tempra-color-border);\n  list-style: none;\n}\n\n.folder-list > li {\n  border-bottom: 1px solid var(--tempra-color-border);\n}\n\n.folder-row {\n  display: grid;\n  grid-template-columns: minmax(0, 1fr) minmax(0, 170px) 56px;\n  align-items: center;\n  gap: 20px;\n  padding: 13px 6px;\n  color: var(--tempra-color-text);\n  text-decoration: none;\n}\n\n.folder-row:hover {\n  background: var(--tempra-color-hover);\n}\n\n.folder-sub {\n  grid-template-columns: minmax(0, 1fr) auto;\n}\n\n.folder-main {\n  display: flex;\n  flex-direction: column;\n  min-width: 0;\n}\n\n.folder-title,\n.folder-desc {\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.folder-title {\n  font-weight: var(--tempra-weight-medium);\n}\n\n.folder-sub .folder-title {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n\n.folder-sub .folder-title svg {\n  flex: none;\n  color: var(--tempra-color-muted);\n}\n\n.folder-desc {\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-ui);\n}\n\n.folder-by {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  min-width: 0;\n  overflow: hidden;\n  color: var(--tempra-color-faint);\n  font-size: var(--tempra-text-meta);\n  white-space: nowrap;\n}\n\n.folder-by .avatar-mark {\n  width: var(--tempra-avatar-small);\n  height: var(--tempra-avatar-small);\n  font-size: var(--tempra-text-initial);\n}\n\n.folder-marks {\n  display: flex;\n  align-items: center;\n  justify-content: flex-end;\n  gap: 8px;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n  font-variant-numeric: tabular-nums;\n}\n\n.folder-threads {\n  display: inline-flex;\n  align-items: center;\n  gap: 3px;\n}\n\n/* Trust as a dot: filled in ink when a person verified the current version, hollow when not. */\n.folder-dot {\n  display: inline-block;\n  flex: none;\n  width: 8px;\n  height: 8px;\n  border: 1.5px solid var(--tempra-color-muted);\n  border-radius: 50%;\n  vertical-align: middle;\n}\n\n.folder-dot.verified {\n  background: var(--tempra-color-muted);\n}\n\n/* A phone: who and the marks go on a second line; the controls are touch targets. */\n@media (max-width: 900px) {\n  .folder-row {\n    grid-template-columns: minmax(0, 1fr) auto;\n    gap: 6px 12px;\n  }\n\n  .folder-row .folder-main {\n    grid-column: 1 / -1;\n  }\n\n  .folder-sub .folder-main {\n    grid-column: auto;\n  }\n}\n\n/*\n * The public pages (TEMPRA-110): the landing page (site/, tempra.dev) and the app's server pages\n * (sign-in, app consent, the email-change link, error pages). Take 3's look without the\n * workspace: the ground, the wordmark, the page as one sheet with a hairline edge, a quiet foot.\n * Nothing here needs a script.\n */\n\n/* The wordmark: the tile with the initial, as the sidebar's library switcher draws it, and the\n   name. */\n.wordmark {\n  display: inline-flex;\n  align-items: center;\n  gap: 10px;\n  color: var(--tempra-color-text);\n  font-size: var(--tempra-text-name);\n  font-weight: var(--tempra-weight-strong);\n  text-decoration: none;\n}\n\n.wordmark:visited,\n.wordmark:hover {\n  color: var(--tempra-color-text);\n}\n\n/* The frame: a column on the ground, the sheet in the middle of it. */\n.public {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  min-height: 100dvh;\n  padding: 0 16px var(--tempra-space-4);\n}\n\n.public-head,\n.public-foot,\n.public-sheet {\n  width: 100%;\n  max-width: var(--tempra-page-width);\n}\n\n.public-head {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n  min-height: var(--tempra-bar);\n  padding: 8px 4px;\n}\n\n.public-nav {\n  display: flex;\n  align-items: center;\n  gap: 16px;\n  font-size: var(--tempra-text-ui);\n}\n\n.public-nav a:not(.button) {\n  color: var(--tempra-color-muted);\n  text-decoration: none;\n}\n\n.public-nav a:not(.button):hover {\n  color: var(--tempra-color-text);\n}\n\n.public-sheet {\n  padding: 48px var(--tempra-sheet-pad) 56px;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-card);\n  background: var(--tempra-color-bg);\n}\n\n/* A form or a message (the server pages): a narrower column, the wordmark and foot with it. */\n.public.narrow .public-head,\n.public.narrow .public-foot,\n.public.narrow .public-sheet {\n  max-width: 560px;\n}\n\n.public-sheet > :first-child {\n  margin-top: 0;\n}\n\n.public-sheet > :last-child {\n  margin-bottom: 0;\n}\n\n.public-foot {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 4px 16px;\n  padding: 16px 4px;\n  color: var(--tempra-color-faint);\n  font-size: var(--tempra-text-meta);\n}\n\n.public-foot a {\n  color: inherit;\n  text-decoration: none;\n}\n\n.public-foot a:hover {\n  color: var(--tempra-color-text);\n}\n\n/* ---------- The landing page ---------- */\n\n.public-sheet section + section {\n  margin-top: 56px;\n}\n\n.lede {\n  max-width: 34em;\n  margin: 12px 0 24px;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-reader);\n  line-height: var(--tempra-line-height);\n}\n\n.public-actions {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n}\n\n/* What Tempra does: short cards between hairlines, two to a row where there is room. */\n.features {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(min(100%, 16rem), 1fr));\n  gap: 10px;\n  margin: 16px 0 0;\n  padding: 0;\n  list-style: none;\n}\n\n.features li {\n  padding: 16px 18px;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-box);\n}\n\n.features h3 {\n  margin: 0 0 4px;\n  font-size: var(--tempra-text-ui);\n  font-weight: var(--tempra-weight-strong);\n}\n\n.features p {\n  margin: 0;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-ui);\n  line-height: var(--tempra-line-height);\n}\n\n/* Steps: numbered in the faint grey, one to a line. */\n.steps {\n  margin: 16px 0 24px;\n  padding: 0;\n  list-style: none;\n  counter-reset: step;\n}\n\n.steps li {\n  display: flex;\n  gap: 12px;\n  padding: 10px 0;\n  border-top: 1px solid var(--tempra-color-border);\n  counter-increment: step;\n}\n\n.steps li:last-child {\n  border-bottom: 1px solid var(--tempra-color-border);\n}\n\n.steps li::before {\n  content: counter(step);\n  min-width: 1.25rem;\n  color: var(--tempra-color-faint);\n  font-variant-numeric: tabular-nums;\n}\n\n/* Terms and privacy: plain text at a comfortable measure. */\n.legal {\n  max-width: 38em;\n}\n\n.legal li + li {\n  margin-top: 8px;\n}\n\n@media (max-width: 640px) {\n  .public {\n    padding: 0 var(--tempra-gutter) var(--tempra-space-3);\n  }\n\n  .public-sheet {\n    padding: 28px 20px 36px;\n  }\n\n  .public-nav a:not(.button) {\n    display: inline-flex;\n    align-items: center;\n    min-height: var(--tempra-touch);\n  }\n}\n";

